INSERT INTO public.daily_questions (cycle_day, category, question, options, correct_index, explanation) VALUES
  (1, 'Ciblage publicitaire', 'Sans ciblage avancé, quelle régie permet d''atteindre des mineurs ?', ARRAY['Snapchat', 'TikTok', 'META'], 0, 'Snapchat est la seule plateforme du dispositif Link qui autorise le ciblage des mineurs sans ciblage avancé. C''est un point clé dès qu''une campagne vise un public très jeune.'),
  (2, 'Ciblage publicitaire', 'Comment LinkedIn estime-t-il l''âge d''un utilisateur ?', ARRAY['Via la date de naissance déclarée', 'À partir du dernier diplôme renseigné', 'D''après l''année de création du profil', 'Selon l''ancienneté du premier poste'], 1, 'LinkedIn infère l''âge à partir du dernier diplôme, pas d''un déclaratif d''âge. Le ciblage par tranche d''âge y est donc peu fiable.'),
  (3, 'Ciblage publicitaire', 'Quelle est la logique de « ciblage » propre à Google Search ?', ARRAY['On cible uniquement par centres d’intérêt', 'On ne cible que les comptes Google connectés', 'On achète des mots-clés, sans ciblage classique'], 2, 'Sur Search, il n''y a pas de ciblage d''audience classique : on achète des requêtes. La diffusion dépend des mots-clés achetés et de la zone.'),
  (4, 'Ciblage publicitaire', 'Quelles catégories spéciales META imposent une diffusion sans ciblage détaillé ?', ARRAY['Crédit, emploi, logement, enjeux sociaux/politiques', 'Mode, beauté, alimentation', 'Voyage, éducation, high-tech'], 0, 'Crédit, emploi, logement et enjeux sociaux/politiques sont des catégories spéciales META. Elles se diffusent sans ciblage avancé, pour les 18-65 ans, avec un rayon minimum de 50 km.'),
  (5, 'Ciblage publicitaire', 'Avant une campagne Spotify, quelle étape est indispensable côté Link ?', ARRAY['Réaliser une étude de potentiel', 'Limiter le ciblage aux capitales', 'Activer uniquement le ciblage par âge', 'Désactiver le ciblage géographique'], 0, 'Une étude de potentiel est incontournable sur Spotify : l''équipe vérifie le volume de comptes et le maximum d''impressions possible sur la zone demandée.'),
  (6, 'Ciblage publicitaire', 'Quel budget quotidien minimum TikTok impose-t-il ?', ARRAY['10 € par jour', '20 € par jour, tous ciblages confondus', '50 € par jour et par ciblage'], 2, 'TikTok demande 50 € par jour et par ciblage d''achat d''espace (soit 50 € PDV/jour/ciblage). Un ciblage supplémentaire relance ce plancher.'),
  (7, 'Ciblage publicitaire', 'Quelle option géographique n''existe pas sur Spotify ?', ARRAY['Ciblage par pays', 'Ciblage par région ou ville', 'Ciblage par rayon autour d’un point', 'Ciblage par codes postaux'], 2, 'Spotify accepte pays, régions, villes et codes postaux, mais pas le rayon autour d''un point. Il faut donc penser la zone autrement qu''en « X km autour du magasin ».'),
  (8, 'Ciblage publicitaire', 'Que permet une correspondance en requête large sur Search ?', ARRAY['Uniquement la requête tapée à l’identique', 'Synonymes, variantes et expressions connexes', 'Uniquement les mots dans le même ordre'], 1, 'La requête large ouvre l''annonce aux synonymes et variantes. Elle est moins précise mais laisse l''algorithme tester et découvrir de nouvelles requêtes.'),
  (9, 'Ciblage publicitaire', 'En expression exacte, l''annonce peut s''afficher quand…', ARRAY['Des mots s’intercalent au milieu de l’expression', 'N’importe quel synonyme apparaît', 'L''expression est présente, avec éventuellement des mots avant ou après'], 2, 'L''expression exacte (phrase) autorise des mots avant ou après, mais pas au milieu. C''est un entre-deux entre large et mot clé exact.'),
  (10, 'Ciblage publicitaire', 'Quel est l''intérêt principal du mot-clé exact ?', ARRAY['Laisser l’algorithme explorer largement', 'Contrôler au plus près la requête qui déclenche l’annonce', 'Couvrir tous les synonymes automatiquement', 'Remplacer le ciblage géographique'], 1, 'Le mot-clé exact n''affiche l''annonce que si la requête correspond très étroitement au terme acheté. C''est précis, mais cela bride l''exploration de l''algorithme.'),
  (11, 'Ciblage publicitaire', 'Pour une catégorie spéciale META, quelles contraintes géo et âge s''appliquent ?', ARRAY['13-17 ans et rayon de 5 km', '18-65 ans et rayon d’au moins 50 km', 'Pas de contrainte d’âge, rayon libre'], 1, 'Les catégories spéciales se diffusent pour les 18-65 ans, sans ciblage détaillé, dans un rayon d''au moins 50 km. C''est une contrainte réglementaire de la régie.'),
  (12, 'Ciblage publicitaire', 'Pourquoi le ciblage par âge est-il peu pertinent sur LinkedIn ?', ARRAY['Parce que LinkedIn interdit toute donnée démographique', 'Parce que seuls les 18-24 ans sont joignables', 'Parce que l’âge se base sur la date de création du compte', 'Parce que l''âge y est inféré du diplôme, pas déclaré'], 3, 'LinkedIn ne s''appuie pas sur un âge déclaré : il déduit une fourchette à partir du dernier diplôme. Les tranches d''âge y sont donc approximatives.'),
  (13, 'Ciblage publicitaire', 'Parmi ces zones, lesquelles Spotify sait cibler ?', ARRAY['Pays, régions, villes ou codes postaux', 'Uniquement le pays entier', 'Uniquement un rayon de 10 km'], 0, 'Spotify couvre pays, régions, villes et codes postaux. Le rayon n''est pas proposé, contrairement à META ou à la cartographie Link.'),
  (14, 'Ciblage publicitaire', 'Sur Google Display, peut-on fournir au client la liste exhaustive des sites de diffusion ?', ARRAY['Oui, Google l’exporte avant lancement', 'Non, le ciblage Display est largement automatisé', 'Oui, mais uniquement pour YouTube'], 1, 'Display s''appuie sur des ciblages automatisés (intérêts, thèmes, mots-clés, sites). On ne dispose pas d''un listing figé des emplacements à l''avance.'),
  (15, 'Ciblage publicitaire', 'Qu''est-ce qu''une audience lookalike dans le jargon Link ?', ARRAY['Une liste e-mail importée telle quelle', 'Un ciblage uniquement géographique', 'Une audience similaire à une audience source', 'Un groupe d’annonces Search'], 2, 'Le lookalike (audience similaire) part d''une audience source — clients, visiteurs, leads — pour trouver des profils proches. C''est un levier d''extension, pas un simple copier-coller de fichier.'),
  (16, 'Ciblage publicitaire', 'Le remarketing vise principalement…', ARRAY['Des utilisateurs déjà venus sur le site ou ayant interagi', 'Des personnes qui n’ont jamais entendu parler de la marque', 'Uniquement les abonnés organiques'], 0, 'Le remarketing (retargeting) recible celles et ceux qui ont déjà visité le site ou interagi, sans avoir converti. Le pixel / l''API alimentent ces audiences.'),
  (17, 'Ciblage publicitaire', 'Dans l''outil Cartographie, comment compose-t-on une zone locale fine ?', ARRAY['Ville + rayon, département, région ou codes postaux', 'Uniquement par mot-clé Search', 'Uniquement par centre d’intérêt META', 'Uniquement par communauté Spotify'], 0, 'La cartographie Link assemble ville + rayon, département, région ou codes postaux, et estime la population. C''est le brief géographique type avant une demande de potentiel.'),
  (18, 'Ciblage publicitaire', 'Parmi ces secteurs, lequel relève d''une catégorie spéciale META ?', ARRAY['Prêt-à-porter', 'Restauration', 'Crédit immobilier ou consommation'], 2, 'Le crédit (comme l''emploi, le logement et les enjeux sociaux/politiques) est une catégorie spéciale. Elle impose une diffusion sans ciblage détaillé.'),
  (19, 'Ciblage publicitaire', 'Que signifie « pas de ciblage classique » sur Search ?', ARRAY['On achète des mots-clés recherchés par les internautes', 'On n’achète que des impressions Display', 'On cible uniquement par lookalike'], 0, 'Search n''utilise pas un ciblage d''audience type réseaux sociaux : on se positionne sur des requêtes. L''intention de recherche remplace le centre d''intérêt.'),
  (20, 'Ciblage publicitaire', 'Le minimum TikTok de 50 € s''applique…', ARRAY['Une seule fois pour tout le compte', 'Uniquement le premier jour', 'Uniquement si on fait de la conversion', 'Par jour et par ciblage'], 3, 'Le plancher est de 50 € par jour et par ciblage. Deux ad sets = deux fois ce minimum quotidien.'),
  (21, 'Ciblage publicitaire', 'Pourquoi l''étude de potentiel Spotify est-elle liée aux impressions ?', ARRAY['Parce que Spotify n’a pas de données d’audience', 'Parce qu’elle remplace le budget', 'Parce qu’elle indique le volume de comptes et le max d’impressions sur la zone'], 2, 'L''étude de potentiel donne le nombre de comptes disponibles et le plafond d''impressions sur la zone. Sans cela, on risque de vendre une pression irréaliste.'),
  (22, 'Ciblage publicitaire', 'Quelle plateforme est la plus naturelle pour un public adolescent, y compris mineurs ?', ARRAY['LinkedIn', 'Snapchat', 'Google Search B2B', 'Spotify sans étude de potentiel'], 1, 'Snapchat permet de toucher des mineurs sans ciblage avancé. C''est la régie à retenir pour les campagnes très jeunes, sous réserve des règles de la verticale.'),
  (23, 'Ciblage publicitaire', 'Sur LinkedIn, quel type de critères de ciblage est le plus discriminant ?', ARRAY['Les goûts musicaux', 'Fonction, secteur, ancienneté, entreprise', 'Le rayon de 1 km uniquement'], 1, 'LinkedIn se distingue par le ciblage professionnel : métier, secteur, ancienneté, taille d''entreprise. C''est la régie B2B de référence chez Link.'),
  (24, 'Ciblage publicitaire', 'Les fautes d''orthographe et la casse sur Search…', ARRAY['Bloquent toujours la diffusion', 'Obligent à recréer la campagne', 'N’empêchent pas la correspondance, selon le type de mot-clé'], 2, 'Peu importent les mots de liaison, minuscules/majuscules ou fautes : Search peut malgré tout déclencher l''annonce. On ne duplique pas un mot-clé pour chaque faute.'),
  (25, 'Ciblage publicitaire', 'Un ciblage Display par centres d''intérêt sert surtout à…', ARRAY['Toucher des profils selon leurs habitudes / affinités', 'Acheter une requête exacte', 'Remplacer le pixel', 'Cibler uniquement les mineurs'], 0, 'L''audience centres d''intérêt (ex. bien-être) place la bannière auprès de personnes aux affinités proches, sans liste de sites figée.'),
  (26, 'Ciblage publicitaire', 'Un placement YouTube par mot-clé positionne l''annonce…', ARRAY['Uniquement dans Google Shopping', 'Sur des chaînes ou contenus contenant ces termes', 'Uniquement dans les SMS'], 1, 'Le placement par mot-clé YouTube vise des chaînes ou pages dont le contenu contient les termes choisis. Ce n''est pas un achat de requête Search.'),
  (27, 'Ciblage publicitaire', 'Peut-on affiner par centres d''intérêt une campagne META « emploi » en catégorie spéciale ?', ARRAY['Oui, sans limite', 'Uniquement après 7 jours', 'Non, la diffusion se fait sans ciblage détaillé', 'Uniquement sur Instagram'], 2, 'Emploi est une catégorie spéciale : pas de ciblage avancé, 18-65 ans, rayon ≥ 50 km. On ne « recible » pas par intérêts comme une campagne classique.'),
  (28, 'Ciblage publicitaire', 'Les codes postaux sont-ils un levier géographique Spotify ?', ARRAY['Oui, avec pays, régions et villes', 'Non, uniquement le rayon', 'Uniquement en France métropolitaine hors DOM'], 0, 'Les codes postaux font partie des options Spotify, aux côtés du pays, des régions et des villes. Le rayon, lui, n''existe pas.'),
  (29, 'Ciblage publicitaire', 'Quelle différence géographique clé oppose META et Spotify ?', ARRAY['META n’a aucune option de ville', 'META peut faire du rayon ; Spotify non', 'Spotify n’a que le ciblage mondial'], 1, 'META (et la cartographie Link) gèrent le rayon autour d''un point. Spotify s''arrête aux mailles administratives / codes postaux.'),
  (30, 'Ciblage publicitaire', 'Que vérifie concrètement l''équipe sur une demande de potentiel Spotify ?', ARRAY['Le ranking SEO du client', 'Le nombre de comptes et le plafond d’impressions', 'Le score qualité Facebook uniquement', 'Le taux d’ouverture SMS'], 1, 'L''étude de potentiel Spotify n''est pas cosmétique : elle sécurise le volume de comptes et le maximum d''impressions livrable sur la zone.'),
  (31, 'Ciblage publicitaire', 'Dans le jargon architecture Link, « ciblage » est synonyme de…', ARRAY['Audience', 'Landing page', 'UTM'], 0, 'Ciblage et audience désignent le même étage : le groupe de personnes que l''on veut atteindre. C''est le niveau intermédiaire de l''architecture.'),
  (32, 'Ciblage publicitaire', 'Pour une zone rurale fine, quel maille cartographique est souvent la plus adaptée ?', ARRAY['Le pays entier', 'Uniquement LinkedIn « monde »', 'Uniquement YouTube Shorts', 'Les codes postaux ou un rayon autour de la ville'], 3, 'Codes postaux ou ville + rayon permettent de coller au bassin de chalandise. Un pays entier diluerait la pression et le budget.'),
  (33, 'Ciblage publicitaire', 'Le ciblage par département est surtout utile pour…', ARRAY['Remplacer les mots-clés Search', 'Cibler des mineurs', 'Une maille administrative plus large qu’une ville, plus fine qu’une région'], 2, 'Le département est une maille intermédiaire, proposée dans la cartographie Link. Il convient quand le rayon ou la ville est trop étroit, et la région trop vaste.'),
  (34, 'Ciblage publicitaire', 'Sur Search, qui « décide » en premier de voir l''annonce ?', ARRAY['L’internaute, via sa requête', 'Un lookalike META', 'Le Community Manager'], 0, 'C''est la requête tapée qui déclenche l''enchère Search. D''où l''importance du choix et du type de correspondance des mots-clés.'),
  (35, 'Ciblage publicitaire', '50 € PDV / jour / ciblage TikTok correspond à…', ARRAY['Un CPM garanti', 'Un plafond mensuel', 'Un minimum d’achat d’espace par ad set et par jour', 'Un coût de pixel'], 2, 'C''est un plancher d''achat d''espace : 50 € par jour et par ciblage. Il faut le prévoir dès le chiffrage commercial.'),
  (36, 'Ciblage publicitaire', 'Logement, crédit, emploi, politique : que doivent-ils avoir en commun sur META ?', ARRAY['Un ciblage lookalike 1 % obligatoire', 'Un format Bumper 6 secondes', 'Une diffusion sans ciblage avancé'], 2, 'Ce sont les catégories spéciales META. La régie impose une diffusion large (18-65 ans, rayon ≥ 50 km) sans ciblage détaillé.'),
  (37, 'Ciblage publicitaire', 'Si un client LinkedIn insiste pour « les 25-34 ans uniquement », que lui expliquer ?', ARRAY['Que l’âge y est inféré du diplôme, donc peu fiable', 'Que LinkedIn cible parfaitement l’âge déclaré', 'Que cela remplace le ciblage métier', 'Que c’est obligatoire en catégorie spéciale'], 0, 'L''âge LinkedIn n''est pas un déclaratif : il est déduit du dernier diplôme. Mieux vaut prioriser fonction, secteur et entreprise.'),
  (38, 'Ciblage publicitaire', 'META et TikTok, sans ciblage avancé, peuvent-ils viser des mineurs comme Snapchat ?', ARRAY['Oui, dans les mêmes conditions', 'Non, Snapchat est la seule régie dans ce cas', 'Uniquement META'], 1, 'Snapchat est la seule plateforme du dispositif qui permet de cibler des mineurs sans ciblage avancé. Les autres régies ne se calibrent pas de la même façon.'),
  (39, 'Ciblage publicitaire', 'Quelle correspondance Search est la plus ouverte pour l''algorithme ?', ARRAY['Mot-clé exact', 'Expression exacte', 'Requête large'], 2, 'La requête large laisse le plus de latitude (synonymes, variantes). L''exact bride ; l''expression exacte est un compromis.'),
  (40, 'Ciblage publicitaire', 'Pourquoi lancer en large sur Search n''est pas « du gaspillage » par principe ?', ARRAY['Parce que le large ignore le budget', 'Parce que le large = Display', 'Parce que le large cible les mineurs', 'Parce que l’algorithme peut tester et faire remonter de nouvelles requêtes'], 3, 'Le large est moins précis mais nourrit l''apprentissage. On coupe ensuite les requêtes non pertinentes, comme dans les exemples d''optimisation mots-clés de l''Academy.'),
  (41, 'Ciblage publicitaire', 'Un ciblage Display « audience mots-clés & sites web » retargete surtout…', ARRAY['Uniquement les abonnés LinkedIn', 'Ceux qui ont récemment tapé certains mots-clés ou visité certains sites', 'Uniquement les ouvreurs SMS'], 1, 'C''est un ciblage comportemental Search/Display : requêtes récentes ou sites visités (ex. 20minutes.fr). Ce n''est pas une liste d''emplacements vendue à l''avance.'),
  (42, 'Ciblage publicitaire', 'Une lookalike se construit à partir de…', ARRAY['Un mot-clé exact uniquement', 'Une audience source (clients, visiteurs, convertisseurs)', 'Un Bumper YouTube', 'Un tarif Studio'], 1, 'Sans seed de qualité (fichier clients, visiteurs pixel, leads), la lookalike n''a pas de matière. La source conditionne la qualité.'),
  (43, 'Ciblage publicitaire', 'Quelle condition technique alimente le remarketing site ?', ARRAY['Le pixel / l’API (ou équivalent) qui enregistre les visites', 'Uniquement un post organique CM', 'Uniquement un mot-clé large'], 0, 'Le remarketing site repose sur le tracking : pixel et/ou API Conversion. Sans collecte, pas d''audience de visiteurs à recibler.'),
  (44, 'Ciblage publicitaire', 'Rayon minimum 50 km : dans quel cas META l''impose-t-il ?', ARRAY['Toutes les campagnes de notoriété', 'Catégories spéciales (crédit, emploi, logement, social/politique)', 'Uniquement TikTok'], 1, 'Le rayon de 50 km minimum va avec les catégories spéciales, en plus du 18-65 ans et de l''absence de ciblage détaillé.'),
  (45, 'Ciblage publicitaire', 'Cibler « la communauté de fans » sur Spotify remplace-t-il l''étude de potentiel ?', ARRAY['Non, le potentiel reste incontournable pour valider les volumes', 'Oui, toujours', 'Uniquement en B2B', 'Uniquement hors France'], 0, 'Le ciblage éditorial (communautés, genres) ne dit pas si la zone a assez de comptes. L''étude de potentiel reste obligatoire avant de vendre la campagne.'),
  (46, 'Formats visuels et Studio', 'Quel ratio correspond au format carré Studio ?', ARRAY['1:1 — 1080×1080', '9:16 — 1080×1920', '1.91:1 — 1200×628'], 0, 'Le carré Studio est en 1:1, 1080×1080 px. C''est le format in-feed de référence, notamment sur META.'),
  (47, 'Formats visuels et Studio', 'Le format vertical Studio (stories / shorts) mesure…', ARRAY['1080×1080', '1200×628', '1080×1920 (9:16)', '1920×1080'], 2, 'Le vertical se livre en 1080×1920, ratio 9:16. Il équipe stories, reels, TikTok, Snapchat et Shorts.'),
  (48, 'Formats visuels et Studio', 'Le format horizontal « bannière / in-feed paysage » Studio est…', ARRAY['1:1 1080×1080', '9:16 1080×1920', '1.91:1, souvent 1200×628'], 2, 'L''horizontal standard Studio est en 1.91:1, typiquement 1200×628. Il ne faut pas le confondre avec le 16:9 TV.'),
  (49, 'Formats visuels et Studio', 'Quelle taille correspond au format TV Studio ?', ARRAY['1920×1080', '1080×1920', '1200×628'], 0, 'Le format TV se livre en 1920×1080 (16:9). Il sert notamment l''in-stream YouTube et certains usages programmatiques.'),
  (50, 'Formats visuels et Studio', 'Combien de déclinaisons de format META le Studio demande-t-il en standard ?', ARRAY['Un seul format au choix', 'Trois : carré, vertical et horizontal', 'Deux : carré et story', 'Cinq ratios IAB'], 1, 'META se briefe en 3 formats : carré, vertical et horizontal. Un visuel unique non décliné sous-exploite les placements.'),
  (51, 'Formats visuels et Studio', 'Pour un post sponsorisé LinkedIn, quel couple ratio / taille est recommandé ?', ARRAY['Carré 1080×1080', '9:16 — 1080×1920', '1.91:1 — 1200×627'], 2, 'LinkedIn sponsored post : ratio 1.91:1 et 1200×627 px. Ce format passe correctement desktop et mobile.'),
  (52, 'Formats visuels et Studio', 'Sur META, un carrousel se briefe principalement en…', ARRAY['Uniquement 16:9 TV', 'Uniquement Bumper 6 s', 'Uniquement 4:5 organique', 'Format carré, plusieurs vignettes'], 3, 'Le carrousel META se travaille en carré (2 visuels image et/ou vidéo, 2 à 10 vignettes). Ce n''est pas un format TV.'),
  (53, 'Formats visuels et Studio', 'Performance Max exige notamment…', ARRAY['Uniquement une vidéo YouTube', 'Un visuel décliné carré, vertical et horizontal, plus logos', 'Uniquement un GIF SMS'], 1, 'PMax : 1 visuel image en 3 formats, logo carré + logo bannière, vidéos via liens YouTube. On ne part pas qu''avec une vidéo.'),
  (54, 'Formats visuels et Studio', 'Peut-on mixer images et vidéos dans une même campagne Demand gen ?', ARRAY['Oui, sans limite', 'Uniquement si on a un pixel', 'Non, image ou vidéo, pas les deux dans la même campagne'], 2, 'Demand gen sépare nettement les scénarios image et vidéo. On ne mélange pas les deux dans une même campagne.'),
  (55, 'Formats visuels et Studio', 'Où trouve-t-on les contraintes programmatiques / Mix IAB dans l''Academy ?', ARRAY['Uniquement dans le quiz Snapchat', 'Dans le devis SMS', 'Dans l’onglet Programmatique du guide Studio', 'Dans GA4'], 2, 'Le guide Studio a un onglet dédié aux publicités programmatiques / Mix IAB, avec les livrables attendus. Ce n''est pas un hors-sujet finance ou SEO.'),
  (56, 'Formats visuels et Studio', 'Combien d''allers-retours de validation la grille Studio inclut-elle d''office ?', ARRAY['Aucun', '3 A/R', '1'], 1, 'La grille tarifaire Studio prévoit 3 allers-retours de validation inclus. Au-delà, on sort du forfait standard.'),
  (57, 'Formats visuels et Studio', 'Le guide officiel des formats visuels Link s''intitule…', ARRAY['Guide des formats visuels et des contraintes V8.2', 'Guide RGPD finance', 'Guide SEO blog', 'Guide RH interne'], 0, 'Le PDF « Guide des formats visuels et des contraintes V8.2 » est le référentiel créa. Il se télécharge dans Guides → Documents.'),
  (58, 'Formats visuels et Studio', 'Pour des Shorts YouTube, quel format vidéo privilégier ?', ARRAY['Vertical 9:16', 'Horizontal 1.91:1 uniquement', 'Carré uniquement'], 0, 'Les annonces Shorts s''affichent dans un flux vertical : une vidéo 9:16 (1080×1920) maximise les vues. L''horizontal y est sous-optimal.'),
  (59, 'Formats visuels et Studio', 'Un visuel 1200×628 correspond à quel usage Studio ?', ARRAY['Story TikTok', 'Horizontal 1.91:1 (in-feed / bannière)', 'Format TV 16:9'], 1, '1200×628 est la déclinaison horizontale 1.91:1. Le TV, lui, est en 1920×1080.'),
  (60, 'Formats visuels et Studio', 'PMax : la diffusion 100 % vidéo sans visuels image est-elle possible ?', ARRAY['Oui', 'Uniquement en Demand gen', 'Uniquement en Shopping Link', 'Non, des visuels image restent nécessaires'], 3, 'Chez Link, PMax ne se lance pas en 100 % vidéo sans images. Il faut le visuel décliné aux 3 formats, en plus des liens YouTube éventuels.'),
  (61, 'Formats visuels et Studio', 'Demand gen : combien de logos carrés au minimum ?', ARRAY['1 logo carré obligatoire', 'Aucun', '5 logos TV'], 0, 'Demand gen impose 1 logo carré. Le kit est plus resserré que PMax, qui demande aussi un logo bannière.'),
  (62, 'Formats visuels et Studio', 'META : 1 visuel image et/ou vidéo se décline…', ARRAY['Uniquement en 16:9', 'Aux 3 formats (carré, vertical, horizontal)', 'Uniquement en 4:5 organique', 'Uniquement en GIF'], 1, 'Le brief META standard : un motif créatif, trois ratios. C''est la base du Studio et du mockup.'),
  (63, 'Formats visuels et Studio', 'Le ratio 9:16 correspond à…', ARRAY['1080×1080 feed', '1920×1080 TV', '1080×1920, usage stories / reels / TikTok / Snap'], 2, '9:16 = vertical plein écran. C''est le format mobile natif des stories et du short video.'),
  (64, 'Formats visuels et Studio', 'Le format TV 1920×1080 est un…', ARRAY['16:9', '1:1', '9:16'], 0, '1920×1080 est du 16:9, distinct du 1.91:1 (1200×628) utilisé en in-feed paysage.'),
  (65, 'Formats visuels et Studio', 'LinkedIn 1200×627 vs Studio 1200×628 : que retenir ?', ARRAY['LinkedIn sponsored : 1200×627 / 1.91:1 ; l’horizontal Studio est en 1200×628', 'Ce sont des formats TikTok', 'Ils remplacent le vertical 9:16', 'Ils servent uniquement au SMS'], 0, 'Les deux sont du 1.91:1. LinkedIn spécifie 1200×627 pour le sponsored post ; le Studio horizontal s''écrit souvent 1200×628.'),
  (66, 'Formats visuels et Studio', 'PMax : les vidéos se fournissent comment ?', ARRAY['Fichiers .mov uniquement en pièce jointe e-mail', 'Uniquement en Stories META', 'Via liens YouTube, jusqu’à 5'], 2, 'PMax attend des liens YouTube (jusqu''à 5), pas un mix d''hébergements libres. Sans image, la diffusion 100 % vidéo n''est pas possible.'),
  (67, 'Formats visuels et Studio', 'Demand gen image : jusqu''à combien d''images ?', ARRAY['2', '5', '20', '100'], 2, 'Demand gen accepte jusqu''à 20 images (ou 5 vidéos selon le type de campagne). On ne mixe pas images et vidéos.'),
  (68, 'Formats visuels et Studio', 'Quels wordings PMax sont attendus a minima ?', ARRAY['1 seul titre de 5 caractères', '3 titres, 1 titre long, 2 descriptions', 'Aucun texte, visuel seul'], 1, 'PMax : 3 titres min (jusqu''à 15), 1 titre long min (jusqu''à 5), 2 descriptions min (jusqu''à 5), plus nom d''entreprise, info-bulles, liens annexes et 1 CTA.'),
  (69, 'Formats visuels et Studio', 'Demand gen wordings minimum :', ARRAY['15 titres comme en PMax', 'Aucun CTA', '1 titre long, 1 titre court, 1 description, nom d’entreprise et 1 CTA'], 2, 'Le kit Demand gen est plus compact : titres longs/courts, description, nom d''entreprise et un CTA. Pas de mix image + vidéo.'),
  (70, 'Formats visuels et Studio', 'Un logo bannière en plus du logo carré est obligatoire sur…', ARRAY['Demand gen uniquement', 'Performance Max', 'Snapchat mineurs', 'SMS'], 1, 'PMax demande logo carré et logo bannière. Demand gen n''impose que le logo carré.'),
  (71, 'Formats visuels et Studio', 'Le mockup Stratégie sert surtout à…', ARRAY['Remplacer le pixel', 'Prévisualiser la pub dans le fil d’une plateforme', 'Calculer le RCS'], 1, 'L''outil mockup place logo, visuel, texte et CTA dans un fil Instagram, Facebook, LinkedIn, TikTok ou Snapchat, pour une restitution client.'),
  (72, 'Formats visuels et Studio', 'Dans le mockup, on choisit notamment…', ARRAY['Uniquement un mot-clé exact', 'Uniquement un département INSEE', 'Uniquement un tarif RCS', 'Plateforme et format (carré, story…)'], 3, 'On sélectionne la plateforme et le format, puis on importe les assets. L''export se fait en PNG, avec sauvegarde dans Mes projets.'),
  (73, 'Formats visuels et Studio', 'Les bannières Display Studio relèvent de…', ARRAY['Formats visuels IAB / adaptatifs, pas du sponsored LinkedIn 1200×627 seul', 'Uniquement du 9:16 TikTok', 'Uniquement du Bumper 6 s'], 0, 'Display = bannières adaptatives, images aux tailles standard, parfois vidéo. Ce n''est pas le format unique LinkedIn.'),
  (74, 'Formats visuels et Studio', 'Pourquoi décliner un même visuel aux 3 formats META ?', ARRAY['Parce que Google l’interdit', 'Pour coller aux placements feed, story et paysage', 'Pour cibler des mineurs'], 1, 'Feed, stories/reels et placements horizontaux n''ont pas le même ratio. Une seule taille sera recadrée ou exclue.'),
  (75, 'Formats visuels et Studio', '1080×1080 est le format…', ARRAY['Vertical 9:16', 'TV 16:9', 'Carré 1:1', 'LinkedIn 1.91:1'], 2, '1080×1080 = carré. Le vertical est 1080×1920, le TV 1920×1080, le LinkedIn sponsored 1200×627.'),
  (76, 'Formats visuels et Studio', 'Le Studio classe les devis création notamment en…', ARRAY['Vidéo, graphisme et fixe', 'SEO, SEA et SMO uniquement', 'RH, finance et juridique'], 0, 'La grille Studio (Mon espace) est organisée en vidéo, graphisme et fixe, avec des lignes au tarif ou sur demande.'),
  (77, 'Formats visuels et Studio', 'Conception, tournage, montage Studio sont…', ARRAY['Des lignes « sur demande » avec approche budgétaire', 'Toujours à 50 € comme TikTok', 'Incluses dans le pixel', 'Des formats 9:16'], 0, 'Ces postes vidéo n''ont pas de tarif unitaire figé : on fait une demande d''approche budgétaire (lien Monday).'),
  (78, 'Formats visuels et Studio', 'Un pack motion design Studio est pensé pour…', ARRAY['Une série TV de 52 minutes', 'Un SMS', 'Un format court (30 s max), utilisable en paid'], 2, 'Le pack motion interne est court (30 s max) et peut servir en paid. Ce n''est pas un tournage long.'),
  (79, 'Formats visuels et Studio', 'Les marges de sécurité / zones de texte se consultent…', ARRAY['Dans le guide Studio par plateforme', 'Uniquement dans GA4', 'Uniquement dans Monday SMS'], 0, 'Chaque onglet Studio (META, LinkedIn, TikTok, etc.) détaille contraintes, marges et exemples. C''est le brief créa avant production.'),
  (80, 'Formats visuels et Studio', 'YouTube Bumper : contrainte de durée, pas de ratio. Quelle durée max ?', ARRAY['3 secondes', '15 secondes', '30 secondes', '6 secondes'], 3, 'Le Bumper dure 6 secondes maximum, non ignorable. Le ratio dépend ensuite du placement (in-stream souvent 16:9).'),
  (81, 'Formats visuels et Studio', 'Annonce In-Feed YouTube : elle comprend surtout…', ARRAY['Un SMS 98 %', 'Un carrousel TikTok standard', 'Une miniature + du texte, durée d’au moins 7 s'], 2, 'L''in-feed YouTube (carré) mêle miniature et texte, vidéo d''au moins 7 secondes, cliquable vers la chaîne ou la page de lecture.'),
  (82, 'Formats visuels et Studio', 'In-stream YouTube désactivable : on peut ignorer après…', ARRAY['0 seconde', '5 secondes (durée d’annonce d’au moins 7 s)', '30 secondes obligatoires', '6 secondes comme le Bumper'], 1, 'Les in-stream skippables durent au moins 7 secondes et peuvent être ignorées au bout de 5 secondes. Le Bumper, lui, n''est pas ignorable et plafonne à 6 s.'),
  (83, 'Formats visuels et Studio', 'Pourquoi le format vertical est-il recommandé pour les Shorts pub ?', ARRAY['Parce que Google Shopping l’exige', 'Pour augmenter le nombre de vues dans le flux vertical', 'Parce que LinkedIn n’accepte que le 9:16'], 1, 'YouTube le dit dans le module plateformes : une vidéo verticale augmente les vues des annonces Shorts. L''horizontal y est un compromis pauvre.'),
  (84, 'Formats visuels et Studio', 'Un dark post n''est pas un ratio : c''est…', ARRAY['Un format 1:1 obligatoire', 'Un Bumper', 'Une pub social payante non publiée en organique sur la page'], 2, 'Le dark post est une création diffusée uniquement en paid, invisible sur le fil organique du compte. Le format visuel, lui, suit toujours le guide Studio.'),
  (85, 'Formats visuels et Studio', 'Avant de briefer la créa, la bonne source des tailles est…', ARRAY['Le guide Studio / guide des formats, par régie', 'Un article SEO générique', 'Le tarif RCS', 'Le score qualité seul'], 0, 'Studio (onglets META, Display, Search, LinkedIn, TikTok, Snapchat, Spotify, programmatique) est la référence interne. On n''invente pas les tailles.'),
  (86, 'Plateformes, placements et formats pub', 'Quel format d''image LinkedIn est recommandé pour un sponsored post ?', ARRAY['Carré 1080×1080', 'Rectangulaire 1.91:1, 1200×627', 'Vertical 4:5'], 1, 'Le sponsored post LinkedIn se livre en 1.91:1, 1200×627. C''est le format qui s''affiche correctement mobile et desktop.'),
  (87, 'Plateformes, placements et formats pub', 'Durée maximale d''un Bumper YouTube ?', ARRAY['3 s', '10 s', '6 s', '15 s'], 2, 'Le Bumper est limité à 6 secondes, non ignorable. Idéal pour un message ultra-court en in-stream.'),
  (88, 'Plateformes, placements et formats pub', 'Lequel n''est PAS un format pub TikTok standard du cours ?', ARRAY['Carousel Ads', 'In-Feed Ads', 'TopView'], 0, 'Les Carousel Ads ne font pas partie de l''offre TikTok standard présentée. In-Feed, TopView et Branded Hashtag Challenge oui.'),
  (89, 'Plateformes, placements et formats pub', 'Quel atout du SMS est souligné dans le module plateformes ?', ARRAY['L’absence de régulation', 'Un taux d’ouverture d’environ 98 %', 'Un format 9:16 obligatoire'], 1, 'Le SMS atteint environ 98 % d''ouverture, souvent lu en quelques minutes. C''est un canal d''impact immédiat, pas un média visuel riche.'),
  (90, 'Plateformes, placements et formats pub', 'Feed vs story : quelle différence de placement ?', ARRAY['Ils ont toujours le même ratio 1:1', 'Le feed s’inscrit dans un fil ; la story est plein écran vertical, éphémère', 'La story est uniquement Search', 'Le feed est un Bumper 6 s'], 1, 'Le feed vit dans le fil (souvent carré ou 4:5) ; la story occupe tout l''écran en 9:16. Le brief créa et le mockup changent.'),
  (91, 'Plateformes, placements et formats pub', 'YouTube est décrit comme…', ARRAY['Le 2ᵉ moteur de recherche mondial, après Google', 'Un réseau B2B type LinkedIn', 'Un canal SMS'], 0, 'YouTube est la référence vidéo et le 2ᵉ moteur de recherche mondial. Les pubs se placent en pré-roll, mid-roll ou post-roll.'),
  (92, 'Plateformes, placements et formats pub', 'Google Shopping et Google Play / AdMob sont-ils opérés par Link ?', ARRAY['Oui, comme le Search', 'Uniquement Shopping', 'Uniquement Play', 'Non, ce n’est pas de l’offre Link'], 3, 'Shopping (catalogue, stocks) et les applis via Play / AdMob ne sont pas réalisés par Link. Search, Display, YouTube, PMax et Demand gen oui.'),
  (93, 'Plateformes, placements et formats pub', 'Les annonces Search dynamiques (DSA) chez Link ?', ARRAY['Toujours livrées telles quelles', 'Obligatoires en PMax', 'Non réalisées, car le contenu doit être validé client'], 2, 'Les DSA sont générées depuis le site. Link ne les opère pas : tout contenu pub est validé par le client.'),
  (94, 'Plateformes, placements et formats pub', 'Display : quels types d''annonces sont cités ?', ARRAY['Bannières adaptatives, annonces illustrées, vidéo', 'Uniquement des sponsored posts LinkedIn', 'Uniquement des RCS'], 0, 'Le réseau Display propose des bannières adaptatives, des images aux tailles standard et de la vidéo dans l''environnement Display.'),
  (95, 'Plateformes, placements et formats pub', 'Gmail fait-il partie des inventaires Google Ads évoqués ?', ARRAY['Non, uniquement TikTok', 'Uniquement Spotify', 'Oui, parmi les emplacements Google Ads', 'Uniquement le Studio fixe'], 2, 'Google Ads peut diffuser aussi sur Gmail (annonces sponsorisées dans les mails), en plus de Search, YouTube et Display. Shopping/Play restent hors offre Link.'),
  (96, 'Plateformes, placements et formats pub', 'Un dark post, c''est…', ARRAY['Un post CM visible sur la page', 'Un SMS', 'Une pub paid social non publiée en organique'], 2, 'Le dark post n''apparaît pas sur le fil organique de la page : il vit seulement en média payant. Utile pour tester des messages sans polluer le compte.'),
  (97, 'Plateformes, placements et formats pub', 'TopView TikTok se distingue de l''In-Feed par…', ARRAY['Un emplacement premium d’ouverture de l’app, vs le fil', 'Un format carrousel 10 images', 'Un Bumper 6 s Google', 'Un ciblage Search'], 0, 'TopView est un format d''ouverture premium. L''In-Feed se glisse dans le fil For You. Ce ne sont pas des Carousel Ads.'),
  (98, 'Plateformes, placements et formats pub', 'Le Branded Hashtag Challenge TikTok est…', ARRAY['Un équivalent Bumper YouTube', 'Un format d’engagement autour d’un défi / hashtag de marque', 'Un type de mot-clé Search'], 1, 'C''est un format engageant (défi de marque), cité parmi les formats TikTok du cours, contrairement aux Carousel Ads.'),
  (99, 'Plateformes, placements et formats pub', 'In-stream YouTube Bumper vs skippable :', ARRAY['Les deux durent 30 s', 'Bumper = Shorts uniquement', 'Bumper ≤ 6 s non skippable ; skippable ≥ 7 s, ignorable après 5 s'], 2, 'Deux mécaniques in-stream : Bumper court non ignorable, ou skippable plus long. À ne pas confondre avec l''in-feed ou les Shorts.'),
  (100, 'Plateformes, placements et formats pub', 'Les annonces Shorts YouTube durent au moins…', ARRAY['30 secondes obligatoires', '6 secondes non ignorables comme le Bumper', '98 % d’ouverture', '6 secondes, ignorables à tout moment'], 3, 'Les Shorts ads durent au moins 6 secondes et peuvent être ignorées à tout moment. Le Bumper in-stream, lui, n''est pas skippable.'),
  (101, 'Plateformes, placements et formats pub', 'Une publicité native vise surtout à…', ARRAY['Remplacer le tracking', 'S’intégrer au contenu du support pour paraître moins intrusive', 'Cibler uniquement les mineurs'], 1, 'Le natif épouse le look & feel du site ou du fil. L''examen Link le distingue des bannières clairement publicitaires.'),
  (102, 'Plateformes, placements et formats pub', 'TF1+ apparaît dans…', ARRAY['Les formats Bumper YouTube', 'Les plateformes du calculateur Social media', 'Les catégories spéciales META', 'Les types de mots-clés'], 1, 'TF1+ est une ligne du calculateur (objectif « Sur demande »). Ce n''est pas une régie Academy quiz classique, mais un levier commercial du site.'),
  (103, 'Plateformes, placements et formats pub', 'Spotify côté formats, c''est surtout…', ARRAY['De l’audio (et visuels associés), pas du In-Feed TikTok', 'Du carrousel 10 cartes', 'Du Search textuel'], 0, 'Spotify est la régie audio du dispositif. Les contraintes visuels se lisent dans l''onglet Studio Spotify, distinctes de TikTok ou META.'),
  (104, 'Plateformes, placements et formats pub', 'Snapchat côté placement, on est dans…', ARRAY['Un résultat Search texte', 'Un environnement story / plein écran vertical', 'Un sponsored 1200×627 LinkedIn'], 1, 'Snapchat se joue en vertical plein écran (snap / story). D''où le brief 9:16 et les CTA spécifiques de l''outil CTA.'),
  (105, 'Plateformes, placements et formats pub', 'META peut diffuser sur…', ARRAY['Facebook et Instagram (placements feed, stories, reels…)', 'Uniquement LinkedIn', 'Uniquement Google Play', 'Uniquement SMS'], 0, 'META = Facebook + Instagram, avec une variété de placements. Le Studio demande les 3 formats pour les couvrir.'),
  (106, 'Plateformes, placements et formats pub', 'Le programmatique Display / Mix IAB se briefe…', ARRAY['Via l’onglet programmatique du Studio (livrables IAB)', 'Comme un sponsored LinkedIn unique', 'Comme un SMS 98 %'], 0, 'Le Studio détaille les publicités programmatiques / Mix IAB et les livrables. L''achat programmatique existe bien dans l''écosystème Link.'),
  (107, 'Plateformes, placements et formats pub', 'Une annonce Search textuelle s''affiche…', ARRAY['En story Snapchat', 'En TopView TikTok', 'Dans les résultats de recherche Google, sur une requête', 'En Gmail uniquement'], 2, 'Le Search texte répond à une intention de requête. Ce n''est ni du social vertical ni du Display bannière.'),
  (108, 'Plateformes, placements et formats pub', 'Les titres et descriptions Search s''affichent…', ARRAY['Toujours dans le même ordre figé, sans exception', 'Uniquement en 9:16', 'De façon aléatoire selon la requête ; on peut épingler 1 titre et 1 description'], 2, 'Le lexique le rappelle : titres et descriptions sont assemblés dynamiquement. On peut épingler un titre et une description en première position.'),
  (109, 'Plateformes, placements et formats pub', 'Info-bulles Search, c''est…', ARRAY['Des accroches supplémentaires (ex. livraison gratuite)', 'Un format TikTok', 'Un pixel'], 0, 'Les info-bulles ajoutent des mentions du type « service client 24/7 ». Elles font partie des wordings PMax / Search.'),
  (110, 'Plateformes, placements et formats pub', 'Les liens annexes Search ajoutent…', ARRAY['Des Bumper', 'Des liens vers des pages précises du site, sous l’annonce', 'Des dark posts META', 'Des codes UTM sans URL'], 1, 'Les liens annexes (sitelinks) pointent vers des rubriques du site, chacun avec une description. Ils enrichissent l''annonce Search / PMax.'),
  (111, 'Plateformes, placements et formats pub', 'Images Search, dans le lexique Link, désigne…', ARRAY['Un carrousel TikTok', 'Un format TV uniquement', 'Des visuels dans l’onglet Images des moteurs, liés à une requête'], 2, 'C''est un format search visuel (Google / Bing), pas un In-Feed social. Link le documente dans le lexique.'),
  (112, 'Plateformes, placements et formats pub', 'Un placement « story » demande surtout…', ARRAY['Un 1200×627 LinkedIn', 'Un 1920×1080 uniquement', 'Un texte Search sans visuel', 'Un visuel vertical 9:16'], 3, 'Story = plein écran mobile. Sans 9:16, la créa est recadrée ou peu lisible. Le mockup story sert à le vérifier.'),
  (113, 'Plateformes, placements et formats pub', 'In-Feed TikTok, c''est…', ARRAY['L’ouverture d’app TopView', 'La pub insérée dans le fil For You', 'Un hashtag challenge'], 1, 'L''In-Feed est le format « dans le fil ». TopView et Branded Hashtag Challenge sont d''autres formats ; le carrousel n''est pas l''offre standard du cours.'),
  (114, 'Plateformes, placements et formats pub', 'Pourquoi le SMS n''est-il pas un média « visuel Studio » au même titre que META ?', ARRAY['Parce qu’il n’existe pas chez Link', 'Parce qu’il remplace YouTube', 'Parce que c’est un canal texte à très fort taux d’ouverture, pas un ratio 1:1/9:16'], 2, 'Le SMS (~98 % d''ouverture) est un levier mobile à part, chiffré dans l''outil SMS/RCS. Le Studio traite les formats image/vidéo des régies.'),
  (115, 'Plateformes, placements et formats pub', 'YouTube in-stream se place…', ARRAY['Uniquement dans Google Shopping', 'Uniquement en story Snapchat', 'Avant, pendant ou après une vidéo (pré / mid / post-roll)', 'Uniquement en RCS'], 2, 'Pré-roll, mid-roll, post-roll : c''est l''in-stream. À distinguer de l''in-feed (miniature) et des Shorts.'),
  (116, 'Plateformes, placements et formats pub', 'Une pub « feed » Instagram vs une story : le mockup change surtout…', ARRAY['Le pixel', 'Le cadre (fil vs plein écran) et le ratio', 'Le minimum TikTok 50 €'], 1, 'Même marque, deux expériences. D''où l''intérêt de mockuper carré et story avant validation client.'),
  (117, 'Plateformes, placements et formats pub', 'Parmi les formats Google Ads, lesquels Link n''opère pas ?', ARRAY['Shopping et Play / AdMob', 'Search texte', 'Display bannières', 'YouTube in-stream'], 0, 'Shopping (produits, stocks) et les applis Play/AdMob sont explicitement hors offre. Le reste de la famille Google Ads du site, si.'),
  (118, 'Architecture de campagnes et zones', 'Quels sont les 3 niveaux d''architecture de campagne chez Link ?', ARRAY['Campagne, Ciblage, Visuels', 'Budget, Audience, Créatifs', 'Objectif, Placement, Conversion'], 0, 'La hiérarchie est toujours Campagne (objectif / cadre), Ciblage (audience) puis Visuels (créas). Les noms d''objets varient selon la régie, pas le principe.'),
  (119, 'Architecture de campagnes et zones', 'Sur META, un avantage d''une campagne mono-zone est…', ARRAY['Une répartition égale automatique entre 20 villes', 'D’être plus fort en enchères grâce à un budget concentré', 'L’obligation de 15 zones'], 1, 'Le budget se paramètre à l''échelle campagne : une seule zone concentre la mise, donc plus de puissance aux enchères. Le multi-zone dilue.'),
  (120, 'Architecture de campagnes et zones', 'Sur TikTok, budget, zone et dates se règlent…', ARRAY['Au niveau campagne uniquement', 'Au niveau du seul visuel', 'Au niveau du compte Google', 'Au niveau des ensembles de publicités (ad set)'], 3, 'TikTok place budget, zone et dates sur l''ad set. Les URL de destination se gèrent plutôt au niveau publicité.'),
  (121, 'Architecture de campagnes et zones', '« Segmentation du ciblage = … »', ARRAY['Optimisations plus poussées', 'Réduction automatique des coûts', 'Simplification de la gestion'], 0, 'Plus on segmente, plus on peut optimiser finement (message, budget, coupe). C''est le principe clé de l''architecture Link.'),
  (122, 'Architecture de campagnes et zones', 'Sur META multi-zones, il est recommandé de ne pas dépasser…', ARRAY['3 zones', '5 zones', '10 zones', '15 zones'], 1, 'Au-delà de 5 zones dans une même campagne META, l''algorithme se perd et la répartition de budget devient inefficace.'),
  (123, 'Architecture de campagnes et zones', 'Inconvénient typique d''une campagne multi-zones ?', ARRAY['Toujours plus de puissance d’enchère', 'Interdiction de visuels', 'Personnalisation limitée et budget qui se répartit de façon aléatoire / diluée'], 2, 'L''examen le rappelle : multi-zones = moins de personnalisation locale et un budget qui n''est pas maîtrisé zone par zone comme en mono-zone.'),
  (124, 'Architecture de campagnes et zones', 'Le niveau campagne définit surtout…', ARRAY['L’objectif global, souvent budget et période', 'Uniquement le visuel PNG', 'Uniquement l’UTM content'], 0, 'C''est l''étage supérieur : objectif, cadre budgétaire et dates selon la régie. Le ciblage et les visuels viennent en dessous.'),
  (125, 'Architecture de campagnes et zones', 'Le niveau visuels contient…', ARRAY['Les créations (images, vidéos, textes) montrées à l’audience', 'Uniquement la liste de mots-clés', 'Uniquement le rayon géographique', 'Uniquement le rôle CM'], 0, 'Dernier étage : les assets. Plusieurs visuels sous un même ciblage permettent des tests créa sans recréer l''audience.'),
  (126, 'Architecture de campagnes et zones', 'Ciblage = audience : à quel étage ?', ARRAY['Au-dessus de la campagne', 'À la place du reporting', 'Intermédiaire, entre campagne et visuels'], 2, 'L''audience (démographie, geo, intérêts, listes) vit au milieu de la pyramide. Trop d''audiences mal pensées = usine à gaz ou, à l''inverse, sous-segmentation.'),
  (127, 'Architecture de campagnes et zones', 'Pourquoi trop de zones tue l''algo META ?', ARRAY['META interdit toute geo', 'Les visuels disparaissent', 'Le budget se disperse et l’apprentissage se dilue', 'Le pixel se désinstalle'], 2, 'Chaque zone devient un micro-marché sous-alimenté. D''où le plafond de 5 zones et l''intérêt du mono-zone quand on veut de la puissance.'),
  (128, 'Architecture de campagnes et zones', 'Google Search : on segmente souvent les groupes d''annonces par…', ARRAY['Hashtags TikTok', 'Type de correspondance / thématique de mots-clés', 'Formats 9:16 uniquement'], 1, 'L''architecture Search isole les correspondances et les thématiques (ex. « Audience mots-clés »). Cela rend les optimisations mots-clés lisibles.'),
  (129, 'Architecture de campagnes et zones', 'Display & YouTube : un groupe d''annonces peut correspondre à…', ARRAY['Un unique Bumper LinkedIn', 'Un devis RCS', 'Un type de ciblage (intérêts, placement site, mots-clés…)'], 2, 'On retrouve des groupes du type audience intérêts, placement site web, placement mot-clé. C''est la segmentation qui permet d''optimiser ensuite.'),
  (130, 'Architecture de campagnes et zones', 'PMax : l''architecture se distingue parce que…', ARRAY['On crée 15 ad sets TikTok', 'On fournit un kit d’assets plus qu’un placement figé par groupe', 'On n’a pas d’objectif conversion', 'On cible des mineurs'], 1, 'Performance Max diffuse sur plusieurs inventaires Google à partir d''assets. Ce n''est pas une pyramide ad set / visuel aussi manuelle que META.'),
  (131, 'Architecture de campagnes et zones', 'Demand gen : la structure créa implique…', ARRAY['Forcément 10 zones META', 'Une campagne image ou vidéo, pas un mix', 'Un carrousel TikTok'], 1, 'Demand gen impose un choix de scénario (image XOR vidéo) et un kit plus court. L''architecture suit cette logique d''assets de découverte.'),
  (132, 'Architecture de campagnes et zones', 'Sur META, le budget se paramètre principalement…', ARRAY['Uniquement au pixel', 'Uniquement au mot-clé exact', 'Uniquement en RCS', 'À l’échelle de la campagne'], 3, 'C''est pour cela que le mono-zone est plus puissant en enchères : toute la mise est au niveau campagne, pas éclatée en 10 geos.'),
  (133, 'Architecture de campagnes et zones', 'URL de destination TikTok : plutôt à quel niveau ?', ARRAY['Publicité (visuel)', 'Compte LinkedIn', 'Campagne Search uniquement'], 0, 'Budget / zone / dates = ad set ; URL = publicité. Chaque créa peut donc pointer vers une LP différente si besoin.'),
  (134, 'Architecture de campagnes et zones', 'Une architecture trop plate (1 campagne, 1 ciblage fourre-tout, 1 visuel) limite…', ARRAY['Le RGPD', 'La capacité à optimiser par segment', 'Le format 1:1'], 1, 'Sans segmentation, on ne sait pas ce qui marche (âge, zone, visuel, mot-clé). « Segmentation = optimisations plus poussées ».'),
  (135, 'Architecture de campagnes et zones', 'À l''inverse, trop segmenter sans budget…', ARRAY['Augmente magiquement le Quality Score', 'Remplace le tracking', 'Affame chaque ad set et pourrit l’apprentissage', 'Est obligatoire en Spotify rayon'], 2, 'Chaque ciblage a besoin de volume (cf. plancher TikTok 50 €/j). Segmenter n''excuse pas de sous-alimenter.'),
  (136, 'Architecture de campagnes et zones', 'LinkedIn : l''architecture suit le même principe 3 niveaux, avec…', ARRAY['Campagne, ciblage professionnel, créas sponsored', 'Uniquement des Bumper', 'Uniquement du Search large'], 0, 'Même pyramide, critères d''audience B2B. Le format créa sponsored reste 1.91:1 / 1200×627 en image.'),
  (137, 'Architecture de campagnes et zones', 'Snapchat : on retrouve la logique…', ARRAY['Campagne / ad set / snap (visuel)', 'Uniquement mot-clé exact', 'Uniquement 5 zones META', 'Uniquement PMax assets'], 0, 'Quelle que soit la régie, le cours insiste : toujours le même principe à 3 étages. Snapchat a ses objets, pas une autre philosophie.'),
  (138, 'Architecture de campagnes et zones', 'Mono-zone META : un autre effet collatéral positif est…', ARRAY['L’obligation de 5 villes', 'L’interdiction du remarketing', 'Un message / enchère plus lisibles pour une même geo'], 2, 'Une geo, un budget, des visuels adaptés : reporting et optimisation plus clairs. Le multi-zone sert quand on doit citer plusieurs territoires, dans la limite de 5.'),
  (139, 'Architecture de campagnes et zones', '« Campagne avec plusieurs zones » META : au-delà de 5…', ARRAY['L’algo se perd, la répartition devient inefficace', 'Le Quality Score passe à 10', 'TikTok prend le relais'], 0, 'Le quiz architecture fixe le plafond à 5. Au-delà, mieux vaut splitter les campagnes.'),
  (140, 'Architecture de campagnes et zones', 'Le jargon Link dit que ciblage = audience. Donc un ad set META c''est…', ARRAY['Uniquement un PNG', 'Un UTM medium', 'Un rôle TM organique', 'Un contenant d’audience + placements / budget selon régie'], 3, 'L''ad set (ou équivalent) porte le ciblage. Les visuels en dessous parlent à cette audience.'),
  (141, 'Architecture de campagnes et zones', 'Pourquoi l''architecture est-elle identique « quelle que soit la plateforme » ?', ARRAY['Parce que toutes les régies ont un Bumper', 'Parce que toutes acceptent le rayon Spotify', 'Parce que Campagne / Ciblage / Visuels reste la base ; seules les spécificités changent'], 2, 'L''alerte du module est claire : toujours le même principe. Les onglets META, Display, Search, LinkedIn, TikTok, Snap détaillent les écarts.'),
  (142, 'Architecture de campagnes et zones', 'Google Search n''a pas d''« audience centres d''intérêt » au niveau ad set comme META : on y met…', ARRAY['Des TopView', 'Des groupes de mots-clés / correspondances', 'Des dark posts organiques', 'Des packs motion'], 1, 'L''étage intermédiaire Search, c''est le groupe d''annonces mots-clés. Le « ciblage » est la requête, pas le lookalike.'),
  (143, 'Architecture de campagnes et zones', 'Si le client veut 12 villes nommées sur META, que recommander ?', ARRAY['Tout mettre dans une seule campagne à 12 zones', 'Splitter en plusieurs campagnes pour rester ≤ 5 zones chacune, ou regrouper les geos', 'Passer en Snapchat mineurs'], 1, 'Le plafond de 5 zones est une règle d''architecture, pas un caprice. On découpe ou on agrège (région / rayon) pour garder de la puissance.'),
  (144, 'Objectifs de campagne et tunnel', 'Pour faire connaître une marque au plus large, on choisit surtout…', ARRAY['Conversion', 'Trafic web', 'Notoriété'], 2, 'La notoriété est l''objectif de début de tunnel : impression et couverture, pas encore le formulaire ou l''achat.'),
  (145, 'Objectifs de campagne et tunnel', 'Sur TikTok, quel objectif envoie vers le site ?', ARRAY['Traffic', 'Video views', 'Community interaction', 'App promotion'], 0, 'L''objectif Traffic (trafic) oriente vers le site ou l''app. C''est celui retenu dans l''offre Link pour pousser vers le web.'),
  (146, 'Objectifs de campagne et tunnel', 'Quelle régie propose « Génération de leads » dans sa catégorie Conversion ?', ARRAY['Snapchat', 'LinkedIn', 'TikTok'], 1, 'LinkedIn range la génération de leads dans Conversion. C''est le recueil d''informations de contacts B2B.'),
  (147, 'Objectifs de campagne et tunnel', 'Dans le schéma global, le trafic web se situe…', ARRAY['Avant la notoriété', 'Après la conversion', 'Entre la notoriété et les leads', 'À la place du reporting'], 2, 'Le parcours va notoriété → trafic → leads / conversion. Le trafic est l''étape intermédiaire vers le site.'),
  (148, 'Objectifs de campagne et tunnel', 'Sur META, l''objectif Interactions vise…', ARRAY['Les likes, commentaires et partages', 'Uniquement les achats pixel', 'Uniquement les SMS'], 0, 'Interactions = engagement autour de la publication (j''aime, commentaires, partages). Ce n''est ni du trafic site ni de la conversion.'),
  (149, 'Objectifs de campagne et tunnel', 'Première étape du tunnel Link présenté dans le schéma ?', ARRAY['Convertir', 'Mettre en place', 'Attirer'], 1, 'Avant d''attirer, on « met en place » : audit concurrence, stratégie, outils d''analyse, cibles, objectifs et KPI.'),
  (150, 'Objectifs de campagne et tunnel', 'La phase « Attirer » vise principalement…', ARRAY['La transformation prospect → client', 'La notoriété et la sensibilisation', 'Le reporting Data Studio', 'Le devis RCS'], 1, 'Attirer (étape 1) fait passer l''internaute à visiteur : notoriété, sensibilisation. Ce n''est pas encore la conversion business.'),
  (151, 'Objectifs de campagne et tunnel', 'Les visiteurs deviennent prospects surtout dans…', ARRAY['La phase Considération / Trafic (Convertir)', 'La seule phase organique CM', 'Le Bumper YouTube'], 0, 'C''est la phase 2 (Convertir / considération-trafic) qui qualifie les visiteurs en prospects. Conclure, ensuite, fait le business.'),
  (152, 'Objectifs de campagne et tunnel', 'Quel élément n''appartient PAS à « Mettre en place » ?', ARRAY['Audit concurrence', 'Définir les cibles', 'Objectifs et KPI', 'Conversion des prospects en clients'], 3, 'Transformer les prospects en clients, c''est « Conclure » (phase 3). Mettre en place prépare le dispositif, ça ne vend pas encore.'),
  (153, 'Objectifs de campagne et tunnel', '« + de business » est associé à…', ARRAY['La notoriété seule', 'Le seul CPM', 'La phase Conversions / Conclure'], 2, 'Conclure, c''est la phase 3 : conversions, chiffre d''affaires, « + de business ». Attirer reste de la notoriété.'),
  (154, 'Objectifs de campagne et tunnel', 'Search côté Link : quels objectifs sont retenus ?', ARRAY['Clics (trafic) ou conversion', 'Uniquement impressions Spotify', 'Uniquement interactions META'], 0, 'Search est exclusivement orienté clics ou conversion. Pas d''objectif notoriété « couverture » comme YouTube.'),
  (155, 'Objectifs de campagne et tunnel', 'YouTube, dans l''offre objectifs Link, c''est surtout…', ARRAY['La génération de leads LinkedIn', 'Le RCS', 'La notoriété de marque', 'Le mot-clé exact seul'], 2, 'YouTube est calibré notoriété : toucher large et renforcer la marque. Le calculateur Social media ne propose que « Impressions » sur Youtube.'),
  (156, 'Objectifs de campagne et tunnel', 'Display peut se configurer pour…', ARRAY['Uniquement des leads LinkedIn', 'Uniquement du SMS', 'Notoriété, trafic ou conversion'], 2, 'Display couvre les trois niveaux d''engagement : impressions / notoriété, clics / trafic, conversion.'),
  (157, 'Objectifs de campagne et tunnel', 'Performance Max est utilisé chez Link comme…', ARRAY['Campagne orientée conversion, diffusion automatisée multi-inventaires', 'Campagne SMS', 'Campagne organique CM', 'Campagne rayon Spotify'], 0, 'PMax = conversion (achat, lead, contact, inscription) sur plusieurs inventaires Google, avec un kit d''assets.'),
  (158, 'Objectifs de campagne et tunnel', 'Demand gen sert surtout à…', ARRAY['Remplacer le CM', 'La considération et le trafic qualifié', 'Cibler des mineurs'], 1, 'Demand gen travaille la découverte / considération avec des assets visuels, objectif trafic (clics) côté Link.'),
  (159, 'Objectifs de campagne et tunnel', 'Dans le calculateur, Perf max n''a qu''un objectif :', ARRAY['Likes', 'SMS', 'Conversion'], 2, 'PERF_MAX_OBJECTIVES = Conversion. Demand Gen, lui, est en Clics. YouTube en Impressions.'),
  (160, 'Objectifs de campagne et tunnel', 'Demand Gen dans le calculateur Social media =', ARRAY['Leads LinkedIn', 'Impressions Spotify', 'Réponses événement', 'Clics'], 3, 'L''outil aligne Demand gen sur des clics, cohérent avec le module objectifs (trafic vers le site / la LP).'),
  (161, 'Objectifs de campagne et tunnel', 'META « Clics » vs « Clics sur lien » :', ARRAY['C’est strictement identique', 'Clics = toutes interactions cliquables ; clics sur lien = vers la landing seulement', 'Clics sur lien = likes'], 1, 'Le lexique distingue clic (tout autour de la pub) et clic sur lien (landing uniquement). Le calculateur propose les deux.'),
  (162, 'Objectifs de campagne et tunnel', 'Une campagne de notoriété ne vise pas en premier…', ARRAY['La couverture et les impressions', 'La conversion immédiate', 'La mémorisation de marque', 'Un large public'], 1, 'La notoriété n''est pas un objectif d''achat. Vouloir du ROAS sur une campagne couverture, c''est un faux KPI.'),
  (163, 'Objectifs de campagne et tunnel', 'Le trafic « s''assied » entre…', ARRAY['Notoriété et leads', 'Leads et facture Studio', 'SMS et RCS'], 0, 'Après avoir été vu, l''utilisateur clique vers le site ; ensuite seulement on collectera des leads. C''est le schéma global des objectifs.'),
  (164, 'Objectifs de campagne et tunnel', 'Objectif LinkedIn « Leads » dans le calculateur correspond à…', ARRAY['Un Bumper 6 s', 'La génération de contacts, rangée côté conversion', 'Un dark post Search'], 1, 'LinkedIn expose Leads (et Likes, Impressions, Clics). L''Academy le classe dans Conversion : recueil d''infos professionnelles.'),
  (165, 'Objectifs de campagne et tunnel', 'TikTok « conversion » dans le calculateur, c''est…', ARRAY['Un objectif d’actions de valeur, distinct d’Impressions / Clics', 'Un format Carousel Ads', 'Un UTM medium', 'Un A/R Studio'], 0, 'TikTok propose Impressions, Clics et conversion. Le site web se pousse plutôt en Traffic dans le module objectifs.'),
  (166, 'Objectifs de campagne et tunnel', '« Visites de profil » META sert à…', ARRAY['Pousser vers la page / le compte, pas forcément vers une LP', 'Remplacer le pixel d’achat', 'Faire du Search exact'], 0, 'C''est un objectif d''interactions compte, listé dans le calculateur META / Insta. Ce n''est pas un objectif conversion site.'),
  (167, 'Objectifs de campagne et tunnel', 'Ordre du tunnel Link :', ARRAY['Conclure puis attirer', 'Uniquement SEA puis SMS', 'Mettre en place → Attirer (notoriété) → Convertir (prospects) → Conclure (business)', 'Reporting puis création'], 2, 'Quatre temps : outillage, notoriété, prospects, business. On ne vend pas une conversion sans avoir posé la base.'),
  (168, 'Objectifs de campagne et tunnel', 'Pourquoi bien définir l''objectif avant l''architecture ?', ARRAY['Parce que l’objectif remplace les visuels', 'Parce que l’objectif interdit le tracking', 'Parce que l’objectif dicte KPI, enchères et même formats'], 2, 'L''examen le souligne : un objectif flou produit de mauvais KPI. Notoriété ≠ leads ≠ conversion, y compris dans le calculateur.'),
  (169, 'Objectifs de campagne et tunnel', 'Snapchat côté calculateur propose surtout…', ARRAY['Impressions et Clics', 'Leads LinkedIn', 'Shopping'], 0, 'Snapchat est en objectifs par défaut Impressions / Clics. L''examen évoque impressions et trafic comme visées principales de la régie.'),
  (170, 'Tracking, attribution, UTM, pixel / API', 'Combien d''actions minimum sur le pixel / l''API pour partir en conversion ?', ARRAY['10', '50', '25', '100'], 1, 'Il faut au moins 50 actions collectées pour optimiser en conversion. Pixel et API voient tout le site, pas seulement la campagne, ce qui aide à atteindre ce seuil.'),
  (171, 'Tracking, attribution, UTM, pixel / API', 'Délai d''attribution actuel après un clic ?', ARRAY['3 jours', '14 jours', '7 jours'], 2, 'On est passé de 28 jours à 7 jours post-clic. Une conversion au 8ᵉ jour ne sera plus attribuée à ce clic.'),
  (172, 'Tracking, attribution, UTM, pixel / API', 'Délai d''attribution actuel après une vue sans clic ?', ARRAY['1 jour', '3 jours', '7 jours', 'Aucun (0 jour vue)'], 3, 'Plus d''attribution vue : 0 jour view. Auparavant c''était 7 jours. Seul le clic (7 jours) compte désormais.'),
  (173, 'Tracking, attribution, UTM, pixel / API', 'Pourquoi les stats social (META, TikTok…) ne sont-elles pas « minorées RGPD » comme on pourrait le croire ?', ARRAY['Les régies sont hors RGPD', 'Les utilisateurs ont accepté les CGU à la création du compte', 'Le tracking y est interdit'], 1, 'Le consentement CGU des plateformes autorise la collecte in-app. D''où des volumes de campagne plus complets que sur un site soumis aux cookies.'),
  (174, 'Tracking, attribution, UTM, pixel / API', 'Particularité des rapports Google / YouTube ?', ARRAY['Jamais d’inconnus', 'Pas de délai d’attribution', 'Beaucoup d’« inconnus », car les gens ne sont pas connectés'], 2, 'Beaucoup d''utilisateurs Search / YouTube ne sont pas logués. Les breakdowns âge / sexe affichent donc une forte part d''inconnus.'),
  (175, 'Tracking, attribution, UTM, pixel / API', 'Pour qu''un pixel navigateur trace, il faut que l''utilisateur…', ARRAY['Ouvre simplement le site, quelles que soient les protections', 'Ait un compte LinkedIn', 'Accepte les cookies, sans adblock, hors navigation privée, sans blocage Apple', 'Reçoive un SMS'], 2, 'Cookies acceptés + pas de bloqueur + pas de private browsing + pas de restriction ATT Apple. Sinon le pixel « rate » la visite.'),
  (176, 'Tracking, attribution, UTM, pixel / API', 'Différence clé balises Google vs pixel / API ?', ARRAY['C’est strictement identique', 'Les balises Google ne collectent que pendant la campagne ; pixel / API voient tout le site', 'Le pixel ne marche que sur Search'], 1, 'Le gestionnaire Google ne mesure qu''à partir de la mise en ligne de la campagne, et seulement le trafic de campagne. Pixel / API captent les flux du site en continu.'),
  (177, 'Tracking, attribution, UTM, pixel / API', 'Un UTM, c''est…', ARRAY['Un paramètre ajouté à l’URL de la landing pour tracer l’origine du trafic', 'Un format 9:16', 'Un score qualité', 'Un ad set TikTok'], 0, 'L''UTM s''accroche derrière l''URL. Invisible pour l''internaute, indispensable pour relier sessions analytics et campagnes.'),
  (178, 'Tracking, attribution, UTM, pixel / API', 'Dans la structure UTM Link, utm_source indique…', ARRAY['La plateforme (META, Google, LinkedIn…)', 'Le prénom du CM', 'Le format TV'], 0, 'Exemple du cours : utm_source=META. C''est la régie / la source, pas le nom du visuel.'),
  (179, 'Tracking, attribution, UTM, pixel / API', 'utm_medium dans l''exemple Link correspond à…', ARRAY['Le numéro de téléphone Studio', 'Le mode d’achat ou type de campagne (CPM, CPC…)', 'Le Bumper'], 1, 'utm_medium=CPM (ou CPC, etc.) décrit la logique d''achat. On ne met pas le nom du client dedans.'),
  (180, 'Tracking, attribution, UTM, pixel / API', 'utm_campaign sert à…', ARRAY['Stocker le pixel', 'Remplacer le lookalike', 'Cibler des mineurs', 'Identifier la campagne (ex. 052025META)'], 3, 'C''est le code / nom de campagne. Il doit rester stable pour que les rapports se recoupent.'),
  (181, 'Tracking, attribution, UTM, pixel / API', 'utm_content chez Link pointe souvent vers…', ARRAY['Le nom du groupe d’annonces / ad set ({{adset.name}})', 'Le SIRET du client', 'Le tarif RCS'], 0, 'utm_content={{adset.name}} affine l''analyse au ciblage. Utile pour voir quel ad set amène le trafic site.'),
  (182, 'Tracking, attribution, UTM, pixel / API', 'Si le client a déjà sa propre nomenclature UTM…', ARRAY['On impose toujours la structure Link', 'On l’intègre à la lettre, sans la modifier', 'On supprime tous les UTM', 'On met tout en utm_source=SMS'], 1, 'Deux cas : structure Link par défaut, ou UTM client digitalement mature recopié tel quel. Pas d''hybridation sauvage.'),
  (183, 'Tracking, attribution, UTM, pixel / API', 'Comment reconnaître un lien tracké ?', ARRAY['Un logo 1:1', 'Un Bumper', 'Un ? suivi de paramètres utm_ dans l’URL'], 2, 'Dès qu''on voit ?utm_source=… on est sur un lien tagué. Sans cela, GA4 ne saura pas attribuer la campagne Link.'),
  (184, 'Tracking, attribution, UTM, pixel / API', 'L''API Conversion META se distingue du pixel parce qu''elle…', ARRAY['Fonctionne côté serveur, même si cookies / adblock gênent le pixel', 'Remplace les visuels', 'Cible les mineurs'], 0, 'L''API envoie les événements depuis le serveur. Elle complète le pixel et fiabilise clics, paniers, achats quand le navigateur filtre.'),
  (185, 'Tracking, attribution, UTM, pixel / API', 'Pixel + API ensemble permettent surtout…', ARRAY['Un meilleur suivi des conversions et un algo mieux nourri', 'D’éviter tout brief Studio', 'De faire du Search sans mots-clés', 'De publier des dark posts organiques'], 0, 'Les deux en parallèle remontent plus d''événements. L''algorithme META apprend mieux ; le seuil des 50 actions est plus tenable.'),
  (186, 'Tracking, attribution, UTM, pixel / API', 'Le pixel est un…', ARRAY['Format 1920×1080', 'Mot-clé exact', 'Petit code JS sur le site qui enregistre visites et actions'], 2, 'Sans pixel (ou équivalent), pas de remarketing site ni d''optimisation conversion. C''est le capteur on-site.'),
  (187, 'Tracking, attribution, UTM, pixel / API', 'Pourquoi 50 actions sont plus faciles à atteindre avec pixel / API qu''avec des balises campagne seules ?', ARRAY['Parce qu’ils ignorent le RGPD', 'Parce qu’ils comptent les SMS', 'Parce qu’ils collectent tout le site, pas seulement la diffusion Link', 'Parce qu’ils remplacent GA4'], 2, 'Les flux organiques, SEO, autres campagnes comptent aussi. Les balises Google, elles, ne voient que la période de campagne.'),
  (188, 'Tracking, attribution, UTM, pixel / API', 'Attribution 7/0, concrètement :', ARRAY['Vue 28 jours = oui', 'Clic dans les 7 jours = oui ; vue seule = non', 'Clic 1 jour seulement'], 1, 'Modèle actuel Link : 7 jours clic, 0 jour vue. Une impression sans clic n''attribue plus la conversion.'),
  (189, 'Tracking, attribution, UTM, pixel / API', 'Les UTM sont-ils visibles par l''internaute dans la barre d''adresse ?', ARRAY['Non, ils sont cryptés dans le pixel uniquement', 'Uniquement sur Snapchat', 'Oui, dans l’URL, mais ils n’altèrent pas l’expérience de page'], 2, 'Les paramètres s''affichent dans l''URL. Ils n''empêchent pas la page de fonctionner ; ils servent au client pour mesurer.'),
  (190, 'Tracking, attribution, UTM, pixel / API', 'GA4 vs régies : un écart est normal parce que…', ARRAY['GA4 compte les Bumper', 'Cookies, connexions et modèles d’attribution diffèrent', 'Les régies n’ont pas de clics', 'Le Studio invente les sessions'], 1, 'GA4 dépend des cookies et mesure le site ; les régies mesurent leurs pubs avec leur attribution. La FAQ le tranche : l''écart est attendu.'),
  (191, 'Tracking, attribution, UTM, pixel / API', 'Le blocage Apple (ATT / tracking) impacte surtout…', ARRAY['Le taux d’ouverture SMS de 98 %', 'Le pixel navigateur / IDFA, donc une partie du tracking app / Safari', 'Le format 1200×627'], 1, 'Sans tracking Apple, le pixel rate des utilisateurs iOS. D''où l''intérêt de l''API Conversion côté serveur.'),
  (192, 'Tracking, attribution, UTM, pixel / API', 'Adblock + navigation privée : le pixel…', ARRAY['Voit tout comme l’API serveur', 'Remonte un Bumper', 'Crée un lookalike', 'Ne voit généralement pas la visite'], 3, 'Ce sont deux des quatre conditions du cours. L''API serveur rattrape une partie de ces pertes ; le pixel non.'),
  (193, 'Tracking, attribution, UTM, pixel / API', 'Les statistiques in-app social sont plus « pleines » car…', ARRAY['La mesure se fait dans l’écosystème où le consentement CGU existe déjà', 'Le RGPD ne s’applique jamais', 'Il n’y a pas d’enchères'], 0, 'Facebook, Instagram, Snapchat, TikTok collectent dans leur app après acceptation des CGU. Google/YouTube, plus souvent hors login, affichent des inconnus.'),
  (194, 'Tracking, attribution, UTM, pixel / API', 'À quoi sert le tracking au quotidien TM ?', ARRAY['Remplacer la créa', 'Suivre performances, sources de trafic et conversions pour piloter', 'Éviter les quizzes Academy'], 1, 'Le module tracking le pose dès l''intro : sans mesure, pas d''optimisation ni de bilan. Pixel, balises, UTM et attribution forment le kit.'),
  (195, 'Tracking, attribution, UTM, pixel / API', 'Les balises Google collectent…', ARRAY['Tout l’historique du site dès l’installation, comme le pixel', 'Uniquement les ouvreurs SMS', 'Les données de la campagne pendant sa diffusion, pas tout le site en amont', 'Uniquement les dark posts'], 2, 'Grande différence rappelée en quiz : Google Ads ne « pré-collecte » pas le site. Pixel / API, si.'),
  (196, 'Optimisations et KPI', 'KPI d''optimisation n°1 d''une campagne de clics ?', ARRAY['CPC (en gardant un œil sur le CTR)', 'CPM', 'CPL'], 0, 'On pilote le coût par clic, tout en surveillant le CTR. L''objectif est de faire cliquer au meilleur CPC.'),
  (197, 'Optimisations et KPI', 'Une campagne de conversion se pilote avec combien de facteurs clés ?', ARRAY['3 (CPM, CPA, ROAS)', '1', '2', '8'], 0, 'Conversion = 3 facteurs : CPM, CPA et ROAS. Le cours insiste à regarder surtout CPM et ROAS.'),
  (198, 'Optimisations et KPI', 'Principe fondamental de l''optimisation Link ?', ARRAY['Augmenter le budget chaque matin', 'Changer de régie toutes les 48 h', 'Zoomer de plus en plus dans le détail'], 2, 'On part du global, puis on descend (campagne → ciblage → visuel → mot-clé → heure…). Le zoom, pas le big bang.'),
  (199, 'Optimisations et KPI', 'Que peut-on optimiser sur le digital Link ?', ARRAY['Presque tout : visuels, âges, zones, audiences, mots-clés, heures, placements…', 'Uniquement le logo', 'Uniquement le SIRET'], 0, 'C''est LA force du web face à la programmatique figée : visuels, genres, âges, plateformes, zones, audiences, mots-clés, sites, horaires…'),
  (200, 'Optimisations et KPI', 'Campagne de leads : on surveille surtout…', ARRAY['Uniquement le CTR Search', 'Uniquement le Bumper', 'ROAS shopping uniquement', 'CPM et CPL'], 3, 'Deux facteurs : coût des impressions (CPM) et coût du formulaire (CPL). Le but est de faire remplir, pas seulement cliquer.'),
  (201, 'Optimisations et KPI', 'Sur Google Search, les optimisations reposent avant tout sur…', ARRAY['Les stories 9:16', 'Les communautés Spotify', 'Les mots-clés (CPC + CTR en campagne clics)'], 2, 'Search est particulier : on coupe ou on pousse des requêtes. L''exemple lunettes du module montre des mots-clés à arrêter.'),
  (202, 'Optimisations et KPI', 'Pourquoi Link revendique une optimisation quotidienne vs la programmatique ?', ARRAY['La programmatique interdit les visuels', 'On regarde les campagnes tous les jours et on agit dès que besoin', 'Le Search n’a pas de mots-clés', 'Le pixel s’optimise tout seul sans données'], 1, 'Le module le dit tel quel : on optimise dès que c''est besoin, c''est notre force, contrairement à la programmatique plus « on pose et on laisse ».'),
  (203, 'Optimisations et KPI', 'Un CTR qui s''effondre sur un visuel : premier réflexe ?', ARRAY['Doubler le budget immédiatement', 'Analyser ce visuel / ce ciblage dans le détail, puis tester ou couper', 'Passer en catégorie spéciale'], 1, 'On zoom : quel ad, quel âge, quelle zone ? Tout paramétrage peut bouger. Ce n''est pas qu''un sujet budget.'),
  (204, 'Optimisations et KPI', 'CPC et CTR se regardent ensemble en campagne clics parce que…', ARRAY['Le CTR remplace le pixel', 'Le CPC est un format Studio', 'Un CPC bas avec un CTR nul ne délivre pas l’objectif de clics'], 2, 'Le CPC mesure le coût ; le CTR la pertinence. Les deux racontent si l''annonce fait cliquer efficacement.'),
  (205, 'Optimisations et KPI', 'En conversion, pourquoi garder un œil sur le CPM en plus du ROAS ?', ARRAY['Un CPM qui explose peut casser la rentabilité même si le ROAS tient un temps', 'Le CPM mesure les leads LinkedIn uniquement', 'Le CPM est un UTM', 'Le CPM remplace le 7 jours clic'], 0, 'Les 3 facteurs sont liés. Un trafic trop cher (CPM) finit par dégrader CPA et ROAS. D''où le trio du quiz.'),
  (206, 'Optimisations et KPI', '« Tout paramétrage peut être optimisé » inclut aussi…', ARRAY['Uniquement le nom du fichier PNG', 'Les heures de diffusion', 'Le SIRET'], 1, 'Le cours liste explicitement les heures, en plus des visuels, âges, zones, audiences, mots-clés, sites, placements.'),
  (207, 'Optimisations et KPI', 'Couper un mot-clé Search non pertinent, c''est…', ARRAY['Une infraction RGPD', 'Un dark post', 'Une optimisation classique (exemple lunettes du module)', 'Un Bumper'], 2, 'L''Academy montre un tableau mots-clés : on arrête « lunettes pas cher abonnement » si ça dessert la campagne clics.'),
  (208, 'Optimisations et KPI', 'Tests A/B créa : à quoi ça sert ?', ARRAY['Comparer des versions pour garder celle qui performe', 'Remplacer le ciblage', 'Éviter le tracking'], 0, 'L''examen pose les tests A/B comme levier d''optimisation. On ne « sent » pas : on mesure deux visuels ou deux wordings.'),
  (209, 'Optimisations et KPI', 'Optimiser trop tôt (avant volume) risque de…', ARRAY['Augmenter magiquement le Quality Score', 'Tuer l’apprentissage sur des stats non significatives', 'Remplacer les 50 actions pixel'], 1, 'Zoomer, oui ; mais avec assez de données. Sinon on coupe un ciblage qui n''avait pas eu le temps de parler.'),
  (210, 'Optimisations et KPI', 'Leviers d''optimisation listés dans le module : visuels, âges, zones, audiences, et aussi…', ARRAY['Uniquement le lundi', 'Mots-clés, sites, heures, placements, genres', 'Uniquement le RCS', 'Uniquement Monday'], 1, 'La liste est volontairement large. C''est tout l''argument commercial du digital Link vs un média figé.'),
  (211, 'Optimisations et KPI', 'Campagne clics : un bon CPC avec un CTR très faible suggère…', ARRAY['Une enchère peut-être ok mais une pub peu attractive / mal ciblée', 'Que le ROAS est forcément bon', 'Que le Bumper suffit'], 0, 'On zoom sur visuel, wording, audience, mot-clé. Le CPC n''est pas le seul juge.'),
  (212, 'Optimisations et KPI', 'Campagne leads : un CPL bas mais un CPM hors norme…', ARRAY['Est toujours parfait', 'Oblige à passer en PMax', 'Interdit le pixel', 'Peut cacher une diffusion trop chère ; on regarde les deux'], 3, 'Le quiz fixe CPM + CPL. Un des deux qui dérive justifie un zoom (placements, âges, zones, visuel formulaire).'),
  (213, 'Optimisations et KPI', 'Pourquoi optimiser régulièrement plutôt qu''une fois en fin de campagne ?', ARRAY['Pour dépenser plus vite sans regarder', 'Pour arrêter toutes les campagnes', 'Pour améliorer le ROI en continu et corriger ce qui dérive'], 2, 'L''examen : l''optimisation vise un meilleur ROI. Chez Link, c''est quotidien, pas un rendez-vous de fin de flight.'),
  (214, 'Optimisations et KPI', 'Changer de plateforme toutes les 48 h est-il le principe d''optimisation ?', ARRAY['Non, le principe est le zoom dans le détail, pas le nomadisme de régie', 'Oui, c’est la règle Academy', 'Oui, pour le score qualité'], 0, 'Le piège du quiz : on n''optimise pas en fuyant. On descend dans les données de la campagne en cours.'),
  (215, 'Optimisations et KPI', 'Un âge ou une zone qui sur-délivre : on peut…', ARRAY['Ne rien toucher, seul le visuel compte', 'Passer en catégorie spéciale', 'Réallouer, isoler, renforcer — c’est un paramètre comme un autre', 'Supprimer le pixel'], 2, 'Âges et zones sont dans la liste officielle des leviers. La segmentation d''architecture rend justement ces coupes possibles.'),
  (216, 'Optimisations et KPI', 'Mots-clés, audiences, visuels : le point commun ?', ARRAY['Ils sont figés comme un spot TV acheté', 'Ils dépendent du RCS', 'Ce sont des paramètres actionnables après mise en ligne'], 2, 'Mise en ligne puis optimisation : c''est la méthodo Link. Rien de tout cela n''est « gravé » au go live.'),
  (217, 'Optimisations et KPI', 'En conversion, le ROAS mesure…', ARRAY['Le retour chiffre d’affaires / dépense pub', 'Le taux d’ouverture SMS', 'Le ratio 9:16', 'Le nombre d’A/R Studio'], 0, 'ROAS = revenue / ad spend. C''est l''un des 3 piliers d''optimisation conversion, avec CPM et CPA.'),
  (218, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Search chez Link : on est sur des objectifs…', ARRAY['Uniquement Interactions META', 'Clics ou conversion, pas de notoriété « couverture »', 'Uniquement impressions Spotify'], 1, 'Le module objectifs est clair : Search = trafic site ou conversion. YouTube porte la notoriété vidéo.'),
  (219, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'YouTube dans Google Ads, c''est…', ARRAY['Du SMS', 'Du sponsored 1200×627', 'De la vidéo (in-stream, in-feed, Shorts) sur le 2ᵉ moteur de recherche'], 2, 'YouTube appartient à la famille Google Ads du site, avec ses formats in-stream / in-feed / Shorts.'),
  (220, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Display, c''est…', ARRAY['Uniquement du Search texte', 'Uniquement LinkedIn', 'Uniquement Snapchat', 'Des bannières (adaptatives, images, vidéo) sur le réseau de sites partenaires'], 3, 'Le réseau Display affiche des visuels sur des millions de sites et apps. Ciblage largement automatisé, pas de listing figé.'),
  (221, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Performance Max diffuse…', ARRAY['Uniquement sur TikTok', 'Sur plusieurs environnements Google, à partir d’un kit d’assets', 'Uniquement en organique CM'], 1, 'PMax est multi-inventaires (Search, Display, YouTube, Gmail, Discover…). On fournit assets + wordings, pas un seul placement manuel.'),
  (222, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Demand gen est pensé pour…', ARRAY['Le catalogue Shopping Link', 'La découverte / considération, kit créa plus resserré que PMax', 'Les mineurs Snapchat', 'Le devis Studio fixe'], 1, 'Demand gen capte l''attention sur les environnements visuels Google. Objectif Link : trafic. Pas de mix image + vidéo.'),
  (223, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Shopping est-il réalisé par Link ?', ARRAY['Non (stocks, flux produits, bases…)', 'Oui, comme le Search', 'Uniquement en PMax obligatoire'], 0, 'Le module plateformes l''écrit en italique : Shopping non réalisé par Link. Idem Play / AdMob.'),
  (224, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Les applications via Google Play / AdMob chez Link ?', ARRAY['Cœur de métier TM', 'Hors offre', 'Équivalent SMS'], 1, 'Play et AdMob sont listés comme non réalisés. On ne vend pas ce levier.'),
  (225, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Annonces Search dynamiques (DSA) :', ARRAY['Non opérées, car le contenu doit être validé client', 'Le format par défaut Link', 'Un Bumper', 'Un lookalike'], 0, 'Les DSA extraient le site automatiquement. Link ne les fait pas : tout wording est validé.'),
  (226, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'PMax : minimum de titres courts ?', ARRAY['3 (jusqu’à 15)', '1', '20'], 0, '3 titres minimum, 15 maximum, plus titres longs, descriptions, nom d''entreprise, téléphone, info-bulles, liens annexes, 1 CTA.'),
  (227, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Demand gen : peut-on mixer 10 images et 2 vidéos ?', ARRAY['Oui', 'Uniquement le week-end', 'Non', 'Uniquement avec un pixel 50 actions'], 2, 'Image XOR vidéo. Jusqu''à 20 images ou 5 vidéos, 1 logo carré, wordings plus courts que PMax.'),
  (228, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'PMax sans image, uniquement 5 liens YouTube :', ARRAY['C’est le brief idéal', 'C’est un Demand gen', 'Insuffisant : la 100 % vidéo sans visuels image n’est pas possible'], 2, 'Prérequis PMax : visuel image en 3 formats + logos. La vidéo YouTube s''ajoute, elle ne remplace pas l''image.'),
  (229, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'YouTube côté objectifs Link =', ARRAY['Notoriété de marque', 'Génération de leads Conversion LinkedIn', 'RCS'], 0, 'Une ligne : notoriété. Le calculateur ne propose que Impressions sur Youtube.'),
  (230, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Display : notoriété, trafic et conversion sont…', ARRAY['Interdits', 'Tous proposés', 'Réservés à Spotify', 'Réservés au SMS'], 1, 'Display est le plus souple des leviers Google « classiques » du site sur les objectifs d''engagement.'),
  (231, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Les 3 types de correspondance Search enseignés sont…', ARRAY['In-Feed, TopView, Challenge', 'Carré, vertical, TV', 'Large, expression exacte, mot-clé exact'], 2, 'Requête large, expression exacte (phrase), mot-clé exact : c''est le trio du module ciblage Search.'),
  (232, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Un budget Search trop juste explique souvent…', ARRAY['Que le pixel est cassé à 100 %', 'Que LinkedIn s’arrête', 'Que le Studio refuse les 3 formats', 'Que l’annonce ne sort pas sur toutes les requêtes pertinentes de la zone'], 3, 'FAQ : même optimisé, un budget insuffisant ne couvre pas toutes les recherches. Ce n''est pas forcément un problème de Quality Score seul.'),
  (233, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Enchérir sur sa propre marque en Search, c''est…', ARRAY['Interdit par Google', 'Du SEA branding : protéger la SERP et le message', 'De la programmatique IAB'], 1, 'La FAQ le classe en stratégie de branding SEA. Ça peut concentrer les clics sur le nom de marque, ce qui est voulu.'),
  (234, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Listing des sites Display avant campagne :', ARRAY['Toujours fourni en PDF', 'Oui via Ads Library LinkedIn', 'Non disponible (ciblages automatisés, enchères, intérêts, habitudes)'], 2, 'Audience mots-clés, intérêts, thèmes, placements : la diffusion dépend des enchères gagnées. Pas de listing figé.'),
  (235, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Gmail dans Google Ads ?', ARRAY['Non, uniquement META', 'Uniquement TikTok', 'Oui, cité parmi les inventaires ; Shopping/Play restent hors Link', 'Uniquement Spotify'], 2, 'Search, YouTube, Display, Gmail : famille Google Ads. Shopping et applis : pas Link.'),
  (236, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'PMax logos obligatoires :', ARRAY['Uniquement un favicon SMS', 'Carré + bannière', '5 logos TV'], 1, 'Deux fichiers logo. Demand gen n''impose que le carré.'),
  (237, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Demand gen wordings : CTA et nom d''entreprise sont…', ARRAY['Obligatoires', 'Interdits', 'Réservés à TikTok', 'Équivalents UTM'], 0, '1 titre long min, 1 titre court min, 1 description min, nom d''entreprise et 1 CTA. Kit plus court que PMax.'),
  (238, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Guide Perf Max et Demand gen dans Documents :', ARRAY['C’est le PDF de lecture des performances / optimisation V1.2', 'Un devis SMS', 'Un mockup Snapchat'], 0, '« Guide Performance Ads V1.2 » (intitulé Perf Max et Demand gen) se télécharge dans Guides. Il complète les modules Academy.'),
  (239, 'Google Ads (Search, Display, YouTube, PMax, Demand gen)', 'Search n''a pas de ciblage d''audience classique : on achète…', ARRAY['Des lookalikes 1 %', 'Des mots-clés / requêtes', 'Des TopView'], 1, 'C''est la particularité rappelée en ciblage et en architecture. L''intention de recherche remplace le centre d''intérêt META.'),
  (240, 'META (Facebook / Instagram)', 'META, dans le dispositif Link, recouvre…', ARRAY['Uniquement LinkedIn', 'Uniquement YouTube', 'Uniquement SMS', 'Facebook et Instagram'], 3, 'Les campagnes META pilotent Facebook et Instagram. Le calculateur distingue aussi Insta only et Facebook only.'),
  (241, 'META (Facebook / Instagram)', 'Objectif META « Interactions » =', ARRAY['Likes, commentaires, partages', 'Uniquement les achats API', 'Uniquement les requêtes Search'], 0, 'C''est l''engagement autour de la pub / du post. Le lexique parle aussi d''interactions publication au sens large (clics, enregistrements, etc.).'),
  (242, 'META (Facebook / Instagram)', 'Combien de formats visuels META le Studio demande-t-il ?', ARRAY['1 seul', '3 : carré, vertical, horizontal', '7 IAB', 'Uniquement 16:9'], 1, 'Un motif, trois ratios, pour coller à feed, stories/reels et paysage.'),
  (243, 'META (Facebook / Instagram)', 'Catégories spéciales META :', ARRAY['Mode et beauté uniquement', 'Sport uniquement', 'Crédit, emploi, logement, social/politique — sans ciblage détaillé'], 2, 'Diffusion 18-65 ans, rayon ≥ 50 km, pas de ciblage avancé. Règle de régie, pas un choix créa.'),
  (244, 'META (Facebook / Instagram)', 'Mono-zone META : intérêt enchères ?', ARRAY['Budget campagne concentré = plus de puissance', 'Toujours 12 villes', 'Interdiction du pixel'], 0, 'Le budget vit au niveau campagne. Une geo = une mise, donc de meilleures enchères qu''un budget éclaté.'),
  (245, 'META (Facebook / Instagram)', 'Plafond recommandé de zones dans une campagne META ?', ARRAY['5', '15', '50', 'Illimité'], 0, 'Au-delà de 5, l''algorithme se perd. On scinde les campagnes si le client a trop de villes.'),
  (246, 'META (Facebook / Instagram)', 'Pixel META : obligatoire pour toute campagne ?', ARRAY['Oui, même en notoriété pure sans site', 'Oui, à la place des visuels', 'Non : utile surtout conversion, remarketing, optimisation événements'], 2, 'L''examen rappelle que le pixel n''est pas obligatoire sur toutes les campagnes. Sans site / sans event, une couverture peut vivre sans.'),
  (247, 'META (Facebook / Instagram)', 'L''API Conversion complète le pixel pour…', ARRAY['Remplacer les 3 formats', 'Cibler des mineurs', 'Remonter plus d’événements côté serveur', 'Faire du Search'], 2, 'Même si cookies refusés ou adblock, l''API peut envoyer vue produit, panier, achat. Pixel + API = couple recommandé.'),
  (248, 'META (Facebook / Instagram)', 'Lookalike META, c''est…', ARRAY['Un format 1200×627', 'Une audience similaire à une source (clients, visiteurs…)', 'Un UTM medium'], 1, 'Les algorithmes identifient des jumeaux de l''audience seed. Levier d''extension, pas un ciblage geo.'),
  (249, 'META (Facebook / Instagram)', 'Remarketing META s''appuie surtout sur…', ARRAY['Un mot-clé exact Search', 'Un devis Studio', 'Le pixel / l’API (visiteurs, événements)'], 2, 'Sans capteur on-site, pas d''audience « a visité la LP ». D''où l''importance du tracking avant de vendre du retargeting.'),
  (250, 'META (Facebook / Instagram)', 'Dark post META :', ARRAY['Un post CM épinglé', 'Pub payante non publiée sur le fil organique de la page', 'Un SMS', 'Un groupe Search'], 1, 'On teste des messages en paid sans les afficher aux abonnés organiques. Le CM n''a pas à le poster sur la page.'),
  (251, 'META (Facebook / Instagram)', 'Outil CTA META : les listes dépendent…', ARRAY['Uniquement du rayon Spotify', 'De l’objectif (impressions vs clics / clics sur lien, etc.)', 'Du guide RH'], 1, 'Le site propose des listes CTA META par objectif (impressions, clics…). On ne briefe pas un CTA LinkedIn sur une campagne META.'),
  (252, 'META (Facebook / Instagram)', 'Pige META : on va chercher les pubs concurrentes dans…', ARRAY['Google Shopping Link', 'Le RCS', 'Le quiz CM', 'Meta Ads Library'], 3, 'La pige commerciale ouvre Ads Library META (et Google Transparency, LinkedIn Ad Library) pour archiver des captures.'),
  (253, 'META (Facebook / Instagram)', 'Calculateur : META propose notamment Impressions, Clics, Clics sur lien, Interactions, et aussi…', ARRAY['Visites de profil, réponses événement, leads, conversion', 'Uniquement Shopping', 'Uniquement Play'], 0, 'La liste META_CUSTOM_OBJECTIVES + conversion couvre le tunnel social. YouTube, lui, reste impressions.'),
  (254, 'META (Facebook / Instagram)', 'Carrousel META Studio :', ARRAY['Uniquement 1920×1080', 'Carré, 2 visuels min., 2 à 10 vignettes, plusieurs groupes recommandés', 'Un format TikTok standard du quiz'], 1, 'Ce n''est pas le format unique 1 visuel / 3 ratios. Le carrousel a son brief carré multi-vignettes.'),
  (255, 'META (Facebook / Instagram)', 'Quality score : notation née chez…', ARRAY['Spotify', 'Le lexique SMS', 'Facebook, puis reprise par le marché', 'Monday.com'], 2, 'Le module score qualité l''attribue à Facebook, ensuite généralisé. La note finale = enchère × score qualité.'),
  (256, 'LinkedIn Ads', 'Format image recommandé d''un sponsored post LinkedIn ?', ARRAY['1.91:1 — 1200×627', '9:16 — 1080×1920', '1:1 uniquement'], 0, 'C''est le couple officiel du quiz plateformes. Il s''affiche correctement desktop et mobile.'),
  (257, 'LinkedIn Ads', 'L''âge LinkedIn se base sur…', ARRAY['Le dernier diplôme', 'La date de naissance KYC', 'L’IDFA Apple', 'Le pixel META'], 0, 'Pas de déclaratif d''âge fiable : inférence via le diplôme. On cible métier / secteur plutôt qu''une tranche 25-34.'),
  (258, 'LinkedIn Ads', 'Objectif « Génération de leads » LinkedIn se range dans…', ARRAY['Uniquement notoriété YouTube', 'SMS', 'Conversion'], 2, 'C''est la régie du cours qui expose cet objectif dans Conversion. Idéal B2B pour collecter des contacts.'),
  (259, 'LinkedIn Ads', 'Pourquoi LinkedIn est la régie B2B de référence Link ?', ARRAY['Ciblage professionnel (fonction, secteur, entreprise)', 'Ciblage mineurs', 'Format Bumper 6 s'], 0, 'L''examen : meilleure plateforme publicitaire B2B. Les critères RH/entreprise n''existent pas ainsi sur META ou TikTok.'),
  (260, 'LinkedIn Ads', 'Les CTA LinkedIn de l''outil…', ARRAY['Changent comme META selon impressions vs clics', 'Sont des mots-clés Search', 'Sont des UTM', 'Sont les mêmes quel que soit l’objectif (Postuler, En savoir plus, Demander une démo…)'], 3, 'LINKEDIN_CTA_OPTIONS est unique. META, lui, varie selon l''objectif.'),
  (261, 'LinkedIn Ads', 'Calculateur LinkedIn : objectifs proposés…', ARRAY['Uniquement conversion PMax', 'Uniquement Traffic TikTok', 'Impressions, Clics, Leads, Likes'], 2, 'Quatre objectifs custom. Les leads collent au module Academy Conversion.'),
  (262, 'LinkedIn Ads', 'Pige LinkedIn : bibliothèque officielle ?', ARRAY['Meta Ads Library uniquement', 'LinkedIn Ad Library', 'TF1+', 'Studio fixe'], 1, 'La pige commerciale relie les trois libraries : META, Google Ads Transparency, LinkedIn.'),
  (263, 'LinkedIn Ads', 'Studio LinkedIn : vertical 9:16 ?', ARRAY['C’est le seul format accepté', 'Ce n’est pas le format sponsored post recommandé (plutôt 1.91:1)', 'C’est un Bumper'], 1, 'On briefe 1200×627. Le 9:16 est pour stories / TikTok / Snap, pas le sponsored classique du quiz.'),
  (264, 'LinkedIn Ads', 'Architecture LinkedIn suit…', ARRAY['Une exception à 10 niveaux', 'Uniquement PMax assets', 'Les 3 niveaux Campagne / Ciblage / Visuels, avec audience pro'], 2, 'Même pyramide. L''onglet architecture LinkedIn détaille les spécificités, pas une autre philosophie.'),
  (265, 'LinkedIn Ads', 'Un lead LinkedIn, c''est surtout…', ARRAY['Un contact professionnel collecté (form / génération de leads)', 'Une vue YouTube < 30 s', 'Un ouvreur SMS', 'Un dark post Search'], 0, 'Conversion B2B : on recueille des infos sur les personnes intéressées par l''activité. KPI type CPL, pas ROAS e-commerce.'),
  (266, 'LinkedIn Ads', 'Cibler « les 18-24 ans » comme sur META :', ARRAY['Aussi précis qu’un déclaratif', 'Peu pertinent, l’âge est inféré du diplôme', 'Obligatoire en catégorie spéciale META'], 1, 'On l''explique au client : LinkedIn n''est pas une régie d''âge. Fonction + secteur performent mieux.'),
  (267, 'LinkedIn Ads', 'Mockup LinkedIn sert à…', ARRAY['Générer un pixel', 'Calculer 50 € TikTok', 'Prévisualiser le sponsored dans un fil professionnel', 'Écrire un UTM medium'], 2, 'L''outil mockup inclut LinkedIn parmi Instagram, Facebook, TikTok, Snapchat. Export PNG pour le client.'),
  (268, 'TikTok, Snapchat, Spotify', 'Minimum TikTok d''achat d''espace ?', ARRAY['50 € par jour et par ciblage', '10 € par jour', '50 € une fois par mois'], 0, 'Plancher commercial à connaître avant de vendre un ad set TikTok. Deux ciblages = 100 € / jour.'),
  (269, 'TikTok, Snapchat, Spotify', 'Format TikTok qui n''est PAS dans l''offre standard du cours ?', ARRAY['In-Feed', 'Carousel Ads', 'TopView'], 1, 'Le quiz plateformes écarte le carrousel. On briefe de la vidéo In-Feed / formats engagés, pas un carrousel META-like.'),
  (270, 'TikTok, Snapchat, Spotify', 'Objectif TikTok pour envoyer vers le site ?', ARRAY['Community interaction', 'Traffic', 'App promotion', 'Video views seul'], 1, 'Traffic = site / app. C''est l''objectif encadré dans le module.'),
  (271, 'TikTok, Snapchat, Spotify', 'TikTok : budget, zone, dates se règlent…', ARRAY['Au niveau ad set (ensemble de publicités)', 'Uniquement au pixel', 'Au niveau LinkedIn'], 0, 'Spécificité d''architecture TikTok, contrairement à META où le budget campagne domine.'),
  (272, 'TikTok, Snapchat, Spotify', 'Snapchat est la seule régie qui…', ARRAY['Impose 50 € / jour / ciblage', 'Infère l’âge du diplôme', 'Interdit le vertical', 'Peut cibler des mineurs sans ciblage avancé'], 3, 'Spécificité jeune public. META / TikTok ne se calibrent pas de la même façon sur les mineurs.'),
  (273, 'TikTok, Snapchat, Spotify', 'Objectifs Snapchat souvent cités (examen / calculateur) ?', ARRAY['Leads LinkedIn', 'Shopping Play', 'Impressions et clics / trafic'], 2, 'Calculateur : Impressions et Clics. L''examen évoque impressions et trafic comme visées de campagne Snapchat.'),
  (274, 'TikTok, Snapchat, Spotify', 'CTA Snapchat dans l''outil :', ARRAY['Liste dédiée (Réserver, Écouter, Voir le menu, etc.), identique pour tous les objectifs', 'Identique à LinkedIn', 'Identique aux mots-clés Search'], 0, 'SNAPCHAT_CTA_OPTIONS est propre à la régie. On ne recycle pas les CTA META impressions.'),
  (275, 'TikTok, Snapchat, Spotify', 'Spotify : étape incontournable avant lancement ?', ARRAY['Un Bumper 6 s', 'Un carrousel TikTok', 'Étude de potentiel (comptes + max d’impressions)', 'Un dark post META'], 2, 'Sans potentiel, on ne sait pas si la zone peut délivrer. C''est marqué INCONTOURNABLE dans le quiz ciblage.'),
  (276, 'TikTok, Snapchat, Spotify', 'Spotify ne permet pas…', ARRAY['Le ciblage pays', 'Le ciblage ville', 'Le ciblage par rayon'], 2, 'Pays, régions, villes, CP : oui. Rayon autour d''un magasin : non. La cartographie Link doit s''adapter.'),
  (277, 'TikTok, Snapchat, Spotify', 'Spotify côté objectifs calculateur ?', ARRAY['Impressions', 'Leads', 'Clics Search', 'Conversion PMax'], 0, 'Régie audio de notoriété / couverture. On ne lui vend pas une logique leads LinkedIn.'),
  (278, 'TikTok, Snapchat, Spotify', 'Studio Snapchat / TikTok : ratio dominant ?', ARRAY['1.91:1 LinkedIn', '9:16 vertical', '16:9 TV uniquement'], 1, 'Full screen mobile. Le mockup story / TikTok / Snap sert à valider ce cadre.'),
  (279, 'TikTok, Snapchat, Spotify', 'In-Feed vs TopView TikTok :', ARRAY['Deux noms du même Bumper Google', 'Deux types de mots-clés', 'Fil For You vs emplacement d’ouverture premium'], 2, 'Deux formats officiels du cours, distincts du carrousel (non standard) et du hashtag challenge.'),
  (280, 'TikTok, Snapchat, Spotify', 'Pourquoi ne pas vendre Spotify « comme un META rayon 10 km » ?', ARRAY['Parce que Spotify interdit la France', 'Parce que Spotify est du Search', 'Parce que Spotify est un SMS', 'Parce que le rayon n’existe pas ; il faut une maille ville / CP / région et un potentiel'], 3, 'Double contrainte : pas de rayon + volumes à valider. C''est un brief geo différent.'),
  (281, 'TikTok, Snapchat, Spotify', 'Calculateur TikTok : objectifs ?', ARRAY['Uniquement Likes LinkedIn', 'Impressions, Clics, conversion', 'Uniquement Demand gen'], 1, 'Trois lignes custom. L''Academy insiste sur Traffic pour le site ; le calculateur expose aussi conversion.'),
  (282, 'Score qualité et enchères', 'Le score qualité, c''est…', ARRAY['Un tarif Studio', 'Une évaluation des annonces et landing qui pèse dans les enchères', 'Un format 9:16', 'Un UTM'], 1, 'Il note l''ensemble pubs + pages de destination et détermine le rang. Créé par Facebook, repris par le marché.'),
  (283, 'Score qualité et enchères', 'Note finale d''enchère =', ARRAY['Enchère × score qualité', 'Enchère + score', 'Enchère − score'], 0, 'Exemple du cours : 0,15 € × 9 = 135. Un petit bid avec un gros score peut battre un gros bid médiocre.'),
  (284, 'Score qualité et enchères', 'Critères pris en compte dans le score qualité Link ?', ARRAY['Uniquement le montant du budget', 'Formats, paramétrage, pertinence du ciblage, audiences, objectifs, optimisation', 'Uniquement le logo'], 1, 'Respect des formats / CDC, setup de campagne, ciblage, qualité d''audiences, gestion d''objectifs, optimisation. Tout compte.'),
  (285, 'Score qualité et enchères', 'Un score qualité bas entraîne surtout…', ARRAY['Un moins bon rang et souvent un coût plus élevé pour le même résultat', 'Un Bumper offert', 'L’exemption RGPD', 'Un lookalike gratuit'], 0, 'L''examen : un mauvais score pénalise. D''où l''intérêt de soigner LP, visuels aux bons formats, ciblage pertinent.'),
  (286, 'Score qualité et enchères', 'Origine de cette notation ?', ARRAY['Facebook, puis les autres acteurs', 'Le lexique SMS', 'Monday.com'], 0, 'Le quiz score qualité l''attribue à Facebook. Google Ads a son Quality Score ; l''idée s''est généralisée.'),
  (287, 'Score qualité et enchères', 'Pourquoi le respect des formats Studio impacte le score ?', ARRAY['Parce que 1080×1080 remplace l’enchère', 'Parce que le rayon Spotify le calcule', 'Parce que c’est un critère explicite (cahier des charges / formats de diffusion)', 'Parce que le SMS a un score qualité'], 2, 'Un visuel mal cadré, hors ratio, nuit à l''expérience et donc à la note. Brief Studio = levier d''enchères, pas que d''esthétique.'),
  (288, 'Score qualité et enchères', 'Pertinence du ciblage dans le score : un message B2B servi à une audience grand public…', ARRAY['Augmente toujours le score', 'N’a aucun effet', 'Dégrade la qualité perçue / le rang'], 2, 'Ciblage pertinent = critère. D''où LinkedIn pour le B2B plutôt qu''un META trop large mal calé.'),
  (289, 'Score qualité et enchères', 'L''optimisation continue nourrit le score parce que…', ARRAY['Elle fait partie des critères (pilotage d’objectifs et ajustements)', 'Le score est figé au go live', 'Le score ignore les CTR'], 0, 'On n''obtient pas un 10 en « posant » la campagne. Le zoom quotidien du module optimisations est aussi un sujet d''enchères.'),
  (290, 'Score qualité et enchères', 'Landing page et score qualité :', ARRAY['La LP est hors sujet', 'L’expérience de page entre dans l’évaluation', 'Seule la TV 1920×1080 compte', 'Seuls les UTM comptent'], 1, 'Annonces ET pages de destination. Une LP lente / hors sujet plombe la note, même avec un beau visuel.'),
  (291, 'Score qualité et enchères', 'On peut gagner une enchère avec un bid plus faible si…', ARRAY['On retire les visuels', 'On passe en catégorie spéciale', 'Le score qualité est nettement meilleur'], 2, 'C''est tout l''intérêt de la multiplication Bid × Quality. La créa et le setup valent de l''argent d''enchères.'),
  (292, 'Score qualité et enchères', 'Paramétrage de campagne (objectif, structure, tracking) pèse-t-il ?', ARRAY['Non, seul le CPM compte', 'Non, seul le CM organique compte', 'Non, seul Monday compte', 'Oui, c’est listé parmi les critères'], 3, 'Un mauvais objectif (conversion sans 50 événements) ou une usine à 12 zones META n''aide pas la note globale.'),
  (293, 'Score qualité et enchères', 'Le lexique « Score qualité » rappelle aussi…', ARRAY['Que le score est un format TikTok', 'Pertinence, CTR attendu, expérience de LP ; un bon score peut baisser le CPC', 'Que le score remplace les UTM'], 1, 'Définition Guides / Lexique, alignée avec le module Academy. Qualité = levier de coût, pas un vanity metric.'),
  (294, 'Méthodologie Link et rôles CM / TM', 'Les 4 étapes de la Méthodologie Link ?', ARRAY['Analyse, Stratégie, Exécution, Évaluation', 'SEO, SEA, SMO, SEM', 'Création, Mise en ligne, Optimisation, Reporting'], 2, 'Créa (visuels / vidéos) → mise en ligne (calibrage) → optimisation (ajustements) → reporting (suivi). C''est le fil conducteur Academy.'),
  (295, 'Méthodologie Link et rôles CM / TM', 'Le Community Manager est surtout chargé de…', ARRAY['L’achat Search', 'Le pixel serveur', 'L’animation des réseaux et du contenu organique', 'Les enchères PMax'], 2, 'CM = communauté, contenus organiques, planning éditorial, modération. Visible sur les réseaux de l''annonceur.'),
  (296, 'Méthodologie Link et rôles CM / TM', 'Le Traffic Manager pilote…', ARRAY['Uniquement la modération des commentaires', 'Leviers payants, SEO, SEA et la performance', 'Uniquement le tournage Studio'], 1, 'TM = acquisition web : paid, SEO, SEA, analyse. Ce n''est pas un second CM.'),
  (297, 'Méthodologie Link et rôles CM / TM', 'Pendant quelle étape ajuste-t-on les campagnes selon les résultats ?', ARRAY['Optimisation', 'Création', 'Uniquement le brief', 'Uniquement le mockup'], 0, 'L''optimisation est le temps des ajustements quotidiens. La création a déjà livré les assets ; le reporting raconte.'),
  (298, 'Méthodologie Link et rôles CM / TM', 'Le TM ne travaille-t-il que les réseaux sociaux ?', ARRAY['Non : paid, SEO, SEA, perf — pas uniquement le social', 'Oui, exclusivement Instagram', 'Oui, uniquement Snapchat'], 0, 'L''examen tranche : le TM n''est pas cantonné au social. SEO et SEA font partie du rôle chez Link.'),
  (299, 'Méthodologie Link et rôles CM / TM', 'SEO et SEA sont…', ARRAY['Identiques', 'Complémentaires dans une stratégie digitale', 'Interdits ensemble'], 1, 'SEO = organique search ; SEA = search payant. Le lexique et l''examen les posent comme duo, pas comme substituts.'),
  (300, 'Méthodologie Link et rôles CM / TM', 'Le contenu CM est visible…', ARRAY['Uniquement en dark post', 'Uniquement en PMax', 'Uniquement en SMS', 'Sur les comptes organiques de l’annonceur'], 3, 'Le module rôles le précise : le travail CM se voit sur les réseaux de la marque. Le TM, lui, achète de l''espace.'),
  (301, 'Méthodologie Link et rôles CM / TM', 'La mise en ligne, c''est…', ARRAY['Le calibrage des campagnes (objectifs, ciblages, tracking, UTM…)', 'La seule étape de tournage', 'Le bilan de fin'], 0, 'On paramètre ce qui a été briefé. Ensuite seulement on optimise avec du réel.'),
  (302, 'Méthodologie Link et rôles CM / TM', 'Le reporting dans la méthodo, c''est…', ARRAY['La création des 3 formats', 'Le suivi des performances (bilans interactifs, KPI)', 'Le ciblage mineurs', 'Le pack motion'], 1, 'Quatrième étape : rendre compte. Les modules Rapports / Bilans (Data Studio, maj ≤ 48 h) incarnent ce temps.'),
  (303, 'Méthodologie Link et rôles CM / TM', 'Pourquoi séparer CM et TM chez Link ?', ARRAY['Parce que le CM fait le Search', 'Parce que le TM modère les commentaires', 'Organique / communauté vs paid / SEO / SEA / perf'], 2, 'Deux métiers, deux leviers. Les confondre dans un brief client crée des attentes fausses (ex. demander du community au TM).'),
  (304, 'Lexique et définitions KPI', 'CPM signifie…', ARRAY['Coût pour 1 000 impressions', 'Coût par clic', 'Coût par lead'], 0, 'On paie la visibilité par lots de mille affichages. Utile pour comparer la cherté de la couverture.'),
  (305, 'Lexique et définitions KPI', 'CPC, c''est…', ARRAY['Le coût moyen d’un clic', 'Le coût de 1 000 vues YouTube', 'Le chiffre d’affaires / pub', 'Le taux d’ouverture SMS'], 0, 'Coût total / nombre de clics. KPI central des campagnes de clics.'),
  (306, 'Lexique et définitions KPI', 'CTR =', ARRAY['Revenu / dépense', 'Leads / clics', 'Clics / impressions (taux de clics)'], 2, 'Un CTR élevé signale une pub pertinente pour l''audience. L''examen : les gens cliquent souvent sur l''annonce.'),
  (307, 'Lexique et définitions KPI', 'ROAS =', ARRAY['Clics / impressions', 'Coût / 1 000', 'Chiffre d’affaires généré / dépense pub', 'Ouvertures SMS'], 2, 'Un ROAS 4:1 = 4 € de revenus pour 1 € investi. Pilier des campagnes conversion.'),
  (308, 'Lexique et définitions KPI', 'Clic vs clic sur lien :', ARRAY['C’est le même compteur', 'Clic = tout autour de la pub ; clic sur lien = landing uniquement', 'Clic sur lien = like'], 1, 'J''aime, commentaires, partages, enregistrements comptent dans « clic » au sens large. Seul le clic vers la LP est « clic sur lien ».'),
  (309, 'Lexique et définitions KPI', 'Une landing page, c''est…', ARRAY['Un ad set TikTok', 'Un score qualité', 'La page d’atterrissage conçue pour convertir le trafic de campagne'], 2, 'Offre claire, CTA visible. L''examen insiste : une LP dédiée aligne message pub et destination.'),
  (310, 'Lexique et définitions KPI', 'Lookalike :', ARRAY['Mot-clé exact', 'Audience similaire à une source', 'Format TV', 'Rôle CM'], 1, 'Les plateformes trouvent des jumeaux de vos clients / visiteurs. Extension d''audience, pas geo.'),
  (311, 'Lexique et définitions KPI', 'Remarketing :', ARRAY['Acheter sa marque en Search', 'Recibler ceux qui ont déjà interagi / visité sans convertir', 'Poster en organique'], 1, 'On revient vers les tièdes. Le pixel / l''API alimentent ces listes.'),
  (312, 'Lexique et définitions KPI', 'Pixel :', ARRAY['Un ratio 1:1', 'Un UTM medium', 'Un CTA Snapchat', 'Code de suivi on-site pour mesurer et créer des audiences'], 3, 'Capteur JS. Base du remarketing et de l''optimisation conversion, avec l''API côté serveur.'),
  (313, 'Lexique et définitions KPI', 'SEA vs SEO :', ARRAY['SEA = search payant ; SEO = search organique', 'SEA = réseaux organiques', 'SEO = SMS'], 0, 'SEA = Google Ads / Bing Ads, visibilité immédiate. SEO = travail de fond sur les résultats naturels.'),
  (314, 'Lexique et définitions KPI', 'SMO, c''est…', ARRAY['Le search payant', 'L’optimisation organique sur les réseaux sociaux', 'Le programmatique IAB'], 1, 'SMO = présence Facebook, Instagram, LinkedIn, TikTok… non payante. C''est plutôt le terrain du CM.'),
  (315, 'Lexique et définitions KPI', 'SEM regroupe…', ARRAY['Uniquement le pixel', 'Uniquement le Studio', 'SEO + SEA + SMO', 'Uniquement Monday'], 2, 'Le lexique Link définit le SEM comme l''ensemble search + social optimization. C''est le chapeau, pas un bouton Google Ads.'),
  (316, 'Lexique et définitions KPI', 'Wording :', ARRAY['Les textes autour des visuels (titres, descriptions…)', 'Le rayon géographique', 'Le score qualité'], 0, 'Titres Search, descriptions, CTA, accroches : tout le textual. PMax et Demand gen ont des minima de wordings.'),
  (317, 'Lexique et définitions KPI', 'Vue YouTube si la vidéo dure moins de 30 s :', ARRAY['Une vue = visionnage jusqu’à la fin', 'Les 3 premières secondes', 'Un simple affichage de miniature', 'Un clic SMS'], 0, 'Cas 1 du lexique : < 30 s, vue = vue complète. Cas 2 : > 30 s, vue = au moins les 30 premières secondes.'),
  (318, 'Lexique et définitions KPI', 'Vue YouTube si la vidéo dure plus de 30 s :', ARRAY['Obligatoirement la vidéo entière', '1 seconde', 'Au moins les 30 premières secondes'], 2, 'Cas 2 : on ne exige pas le visionnage total. 30 secondes vues suffisent à compter une vue.'),
  (319, 'Lexique et définitions KPI', 'Une impression, c''est…', ARRAY['Le nombre de fois où la pub s’affiche à l’écran', 'Un clic', 'Un lead'], 0, 'Affichage ≠ engagement. Le CPM facture ces impressions par mille.'),
  (320, 'Bilans, rapports et lecture de performance', 'Pour chaque campagne vendue, Link met à disposition…', ARRAY['Uniquement un SMS de fin', 'Uniquement un mockup', 'Aucun reporting', 'Un bilan en ligne interactif, mis à jour (max 48 h après le début)'], 3, 'Module Rapports : transparence client sur impressions, clics, audiences. Exemple Data Studio + tuto Vimeo.'),
  (321, 'Bilans, rapports et lecture de performance', 'Le bilan de fin de campagne sert à…', ARRAY['Remplacer la création', 'Cibler des mineurs', 'Faire le point KPI, tirer des enseignements et préparer les reco suivantes'], 2, 'Vue complète des résultats. Ce n''est pas qu''un PDF décoratif : ça nourrit le prochain brief.'),
  (322, 'Bilans, rapports et lecture de performance', 'Pourquoi GA4 et les rapports régie divergent souvent ?', ARRAY['Parce que GA4 compte les formats Studio', 'Cookies, utilisateurs non logués, modèles d’attribution différents', 'Parce que les régies n’ont pas de clics', 'Parce que le CM invente les stats'], 1, 'FAQ officielle. GA4 peut sembler plus faible ; c''est normal, pas forcément un bug de campagne.'),
  (323, 'Bilans, rapports et lecture de performance', 'Google / YouTube : beaucoup d''« inconnus » dans les breakdowns car…', ARRAY['Le pixel interdit l’âge', 'Beaucoup d’utilisateurs ne sont pas connectés', 'META masque tout'], 1, 'Même cause que dans le quiz tracking. On l''explique au client plutôt que de « corriger » un âge introuvable.'),
  (324, 'Bilans, rapports et lecture de performance', 'Les stats social sont plus complètes in-app grâce…', ARRAY['À l’absence de RGPD', 'Au format 1:1', 'Aux CGU acceptées à la création du compte'], 2, 'On ne minorise pas META / TikTok comme un site cookie-gated. Le rapport campagne social n''est pas « faux » vs GA4 ; il mesure autre chose.'),
  (325, 'Bilans, rapports et lecture de performance', 'Attribution à lire dans un bilan aujourd''hui :', ARRAY['7 jours clic, 0 jour vue', '28 jours clic, 7 jours vue', '1 jour clic seulement', 'Toujours view-through 7 j'], 0, 'Sans ce cadre, on compare des conversions « vue » d''un ancien modèle à du 7/0 actuel. Pédagogie client obligatoire.'),
  (326, 'Bilans, rapports et lecture de performance', 'Clic vs clic sur lien dans un rapport META :', ARRAY['Les additionner comme des leads', 'Ne pas les confondre : le second est la landing', 'Les traiter comme du ROAS'], 1, 'Un rapport « clics » gonflé d''engagements n''est pas du trafic site. Le lexique est là pour la lecture client.'),
  (327, 'Bilans, rapports et lecture de performance', 'Le reporting est la 4ᵉ étape de la méthodo : il vient…', ARRAY['Avant tout brief', 'À la place du pixel', 'Après création, mise en ligne et optimisation', 'Uniquement en organique'], 2, 'On ne reporte pas dans le vide : les trois temps précédents ont produit de la donnée. Le bilan raconte le pilotage.'),
  (328, 'Bilans, rapports et lecture de performance', 'Un exemple concret de bilan se trouve…', ARRAY['Via le lien Looker / Data Studio du module Rapports', 'Uniquement dans le quiz Snapchat', 'Uniquement dans Ads Library'], 0, 'Le bouton « Exemple concret de bilan » ouvre un reporting type. Le tuto Vimeo montre comment le lire.'),
  (329, 'Bilans, rapports et lecture de performance', 'Lecture Perf Max / Demand gen : le document de référence est…', ARRAY['Le guide mineurs Snapchat', 'Le Guide Perf Max et Demand gen (Performance Ads V1.2)', 'La grille SMS 10 k'], 1, 'Guides → Documents. Il complète les écrans Academy pour expliquer les perfs de ces campagnes automatisées.'),
  (330, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'Le calculateur Social media sert à…', ARRAY['Installer le pixel', 'Chiffrer une stratégie multi-régies et sortir un PDF', 'Remplacer Monday', 'Faire du SEO on-page'], 1, 'Jusqu''à 3 blocs stratégie, KPIs, budgets, plateformes (META, TikTok, LinkedIn, TF1+, Search, PMax…). Outil informatif, sans valeur contractuelle.'),
  (331, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'TF1+ dans le calculateur : objectif affiché ?', ARRAY['Sur demande', 'Conversion PMax', 'Leads LinkedIn'], 0, 'TF1_PLUS_OBJECTIVES = Sur demande. C''est bien une plateforme de l''outil commercial social.'),
  (332, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'Outil SMS / RCS : le seuil 10 k contacts…', ARRAY['N’existe pas', 'Est un format Studio', 'Est un UTM', 'Existe dans la grille (palier SMS / éligibilité RCS)'], 3, 'SMS : palier de PU dès ≤ 10 000. RCS : volume < 10 000 = non éligible (PU -1). Seuil commercial réel du site.'),
  (333, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'RCS / Rich SMS dans l''outil, c''est…', ARRAY['Un Bumper YouTube', 'Un lookalike META', 'Un canal enrichi, avec options (rich SMS, agent conversationnel, ciblage…)'], 2, 'On compose un devis SMS ou RCS : volume, vagues, options rich / agent / base clients. PDF devis, sauvegarde Mes projets.'),
  (334, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'L''agent conversationnel se coche dans…', ARRAY['Les options du devis SMS / RCS', 'Le mockup LinkedIn', 'Le quiz architecture'], 0, 'smsOptions.agent fait partie du chiffrage. Ce n''est pas un objectif Google Ads.'),
  (335, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'Tarifs Studio (Mon espace) permettent de…', ARRAY['Acheter du Search', 'Créer un pixel', 'Monter un devis créa (vidéo / graphisme / fixe) selon la grille', 'Ouvrir Ads Library'], 2, 'Prestations à tarifs ou sur demande, 3 A/R inclus. Accès commerciaux, créa, admins.'),
  (336, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'Conception / tournage / montage Studio :', ARRAY['Toujours 50 € comme TikTok', 'Inclus dans le RCS', 'Sur demande, approche budgétaire (Monday)'], 2, 'Pas de PU figé : clic vers l''approche budgétaire. Le pack motion, lui, a un tarif (ex. 4000 €, 30 s max).'),
  (337, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'Plan Média (Stratégie) sert à…', ARRAY['Simuler volumes, pénétration, pression, stratégies idéale / MAX / perso', 'Modérer les commentaires', 'Envoyer un RCS', 'Épingler un titre Search'], 0, 'Outil admin de simulation multi-plateformes, export PDF, sauvegarde Mes projets. Complémentaire du calculateur de vente.'),
  (338, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'Cartographie :', ARRAY['Écrire des UTM', 'Composer des zones (ville+rayon, département, région, CP) et estimer l’audience', 'Choisir un CTA Snapchat'], 1, 'C''est le brief geo avant potentiel Monday. Spotify (sans rayon) s''appuie plutôt sur villes / CP.'),
  (339, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'Rétroplanning :', ARRAY['Remplacer le pixel', 'Cibler des mineurs', 'Planifier les phases (social, SMS/RCS…) sur un calendrier / Gantt, export PDF'], 2, 'Dates et phases par plateforme, sauvegarde Mon espace. Outil de production / vente, pas un quiz régie.'),
  (340, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'Mes projets centralise…', ARRAY['Uniquement les quizzes Academy', 'Uniquement GA4', 'Uniquement Play Store', 'Stratégies, rétroplanning, studio, plan média, mockups, pige, SMS/RCS'], 3, 'Hub unique : ouvrir, chercher, supprimer. Les admins voient la vue multi-utilisateurs.'),
  (341, 'Outils commerciaux (calculateur, SMS/RCS, tarifs Studio)', 'Le calculateur social est-il contractuel ?', ARRAY['Oui, il remplace le devis signé', 'Non, outil informatif sans valeur contractuelle', 'Oui, comme un pixel'], 1, 'Le guide d''utilisation le rappelle. On s''en sert pour chiffrer et PDF, pas comme bon de commande.'),
  (342, 'FAQ / cas terrain', 'L''annonce Search n''apparaît pas sur toutes les requêtes de la zone. Cause fréquente ?', ARRAY['Absence de Bumper', 'Budget insuffisant pour couvrir la demande', 'Interdiction des UTM', 'Format 9:16 manquant'], 1, 'FAQ : même avec des optimisations, sans budget plus élevé on ne peut pas être présent à chaque recherche pertinente.'),
  (343, 'FAQ / cas terrain', 'Les stats GA4 ≠ rapports campagne. Est-ce anormal ?', ARRAY['Non : cookies, login et attribution expliquent l’écart', 'Oui, toujours un bug pixel à 100 %', 'Oui, le CM a faux'], 0, 'GA4 mesure le site (cookies) ; les régies mesurent leurs pubs. Le résultat « plus faible » côté GA4 est attendu.'),
  (344, 'FAQ / cas terrain', 'Peut-on lister les sites Display à l''avance ?', ARRAY['Oui, Google l’exporte toujours', 'Non, ciblages automatisés (intérêts, thèmes, mots-clés, enchères)', 'Oui, via LinkedIn Ad Library'], 1, 'Exemples du cours : mot-clé « don de sang », site 20minutes.fr, thème bénévolat… La diffusion suit les enchères, pas un listing client.'),
  (345, 'FAQ / cas terrain', 'Beaucoup de clics sur le nom de marque, peu sur le reste :', ARRAY['Souvent du SEA branding (protection SERP + maîtrise du message)', 'Un pixel cassé à coup sûr', 'Un problème de format TV', 'Un minimum TikTok'], 0, 'Enchérir sur sa marque n''est pas un échec : ça protège contre les concurrents et dynamise la campagne, même si ça « paraît redondant ».'),
  (346, 'FAQ / cas terrain', 'Display « audience centres d''intérêt » : exemple type du cours ?', ARRAY['Bien-être (affinité), sans liste de sites figée', 'Un sponsored 1200×627', 'Un RCS agent'], 0, 'La FAQ illustre intérêts, thèmes, mots-clés, sites. On explique au client le principe, on ne promet pas leboncoin.fr à 100 %.'),
  (347, 'FAQ / cas terrain', 'Un client compare une conversion « vue 7 jours » d''un vieux rapport au 7/0 actuel. Que dire ?', ARRAY['Rien n’a changé depuis 28 jours clic', 'GA4 ignore toujours les cookies', 'Le modèle a changé : plus d’attribution vue, 7 jours clic seulement', 'Le Studio a modifié le ROAS'], 2, 'Pédagogie terrain issue du module tracking. Sans ça, le bilan « a chuté » alors que c''est la règle d''attribution.'),
  (348, 'FAQ / cas terrain', 'Beaucoup d''inconnus âge/sexe sur YouTube dans le bilan client :', ARRAY['Preuve que la campagne n’a pas diffusé', 'Preuve d’un dark post', 'Normal si les gens ne sont pas logués'], 2, 'Même réponse qu''en quiz tracking, version rendez-vous client. On ne « répare » pas des inconnus Google.'),
  (349, 'FAQ / cas terrain', 'Le client veut le détail heure par heure dès J+0 du bilan en ligne :', ARRAY['Le module indique une maj en temps réel, max 48 h après le début', 'Les bilans n’existent pas', 'Il faut attendre la fin de campagne uniquement'], 0, 'On pose le cadre : interactif, transparent, mais pas forcément la minute 1. Le bilan de fin, lui, consolide les enseignements.'),
  (350, 'Veille, mockup, CTA, potentiels', 'La pige commerciale s''appuie sur…', ARRAY['Uniquement TikTok organic', 'Meta Ads Library, Google Ads Transparency, LinkedIn Ad Library', 'Uniquement Spotify Fan Study', 'Uniquement le lexique SMO'], 1, 'Trois bibliothèques officielles + import multi-captures dans un projet Mes projets. C''est de la veille concurrentielle paid.'),
  (351, 'Veille, mockup, CTA, potentiels', 'Un projet pige peut contenir…', ARRAY['Un seul PNG à vie, jamais plus', 'Uniquement des UTM', 'Plusieurs captures d’annonces regroupées sous un nom'], 2, 'À l''enregistrement : un nom de projet, plusieurs fichiers = un seul projet. On rouvre via ?project=.'),
  (352, 'Veille, mockup, CTA, potentiels', 'Le mockup Stratégie prévisualise une pub dans…', ARRAY['GA4', 'Monday uniquement', 'Search texte uniquement', 'Le fil d’une plateforme (Instagram, Facebook, LinkedIn, TikTok, Snapchat)'], 3, 'On importe logo, visuel, texte, CTA ; export PNG. Ancienne URL /mon-espace/mockup redirige vers /strategie/mockup.'),
  (353, 'Veille, mockup, CTA, potentiels', 'Des outils CTA existent pour…', ARRAY['Uniquement Spotify audio', 'LinkedIn, Snapchat et META (listes selon régie / objectif)', 'Uniquement le RCS'], 1, 'platform-cta-options.ts : LinkedIn stable, Snapchat stable, META variable selon impressions vs clics. Brief créa aligné régie.'),
  (354, 'Veille, mockup, CTA, potentiels', 'Les demandes de potentiels se font via…', ARRAY['Un dark post', 'Un Bumper', 'Un brief Monday.com (module Demandes de potentiels)'], 2, 'Page Academy + cartographie : liens Monday (board potentiels). Ce n''est pas un ticket Studio créa.'),
  (355, 'Veille, mockup, CTA, potentiels', 'CTA LinkedIn « Demander une démo » ou « Postuler » :', ARRAY['Sont des objectifs PMax', 'Sont des formats 9:16', 'Font partie de la liste unique LinkedIn de l’outil', 'Sont des UTM source'], 2, 'On choisit le CTA dans la liste officielle, indépendamment de l''objectif impressions / clics / leads.'),
  (356, 'Veille, mockup, CTA, potentiels', 'Un mockup ne remplace pas…', ARRAY['Le PNG d’export', 'Le respect des tailles Studio (on prévisualise, on ne « invente » pas un ratio)', 'Le choix de plateforme'], 1, 'Utile en restitution, mais le brief production reste le guide des formats. Un mockup story mal cadré se voit tout de suite.'),
  (357, 'Veille, mockup, CTA, potentiels', 'Google Ads Transparency dans la pige sert à…', ARRAY['Voir les pubs Search / Display / YouTube des annonceurs', 'Calculer un CPL LinkedIn', 'Envoyer un RCS', 'Noter le Quality Score'], 0, 'Complément de Meta Ads Library et LinkedIn Ad Library. On archive des captures, on n''importe pas les stats régie.'),
  (358, 'Chefferie de projet et production', 'Le guide chefferie de projet décrit…', ARRAY['Diffusion, production, Monday, rapports, devis et besoins clients', 'Uniquement les Bumper YouTube', 'Uniquement le ciblage mineurs'], 0, 'PDF « Guide de la Chefferie de Projet - V1 » dans Guides → Documents. C''est le process production / CP.'),
  (359, 'Chefferie de projet et production', 'Les demandes de potentiels passent par…', ARRAY['Un UTM content', 'Monday.com (brief / board dédié)', 'Un lookalike'], 1, 'Academy Demandes de potentiels + cartographie pointent vers Monday. Le CP / commercial n''envoie pas ça dans un Slack improvisé.'),
  (360, 'Chefferie de projet et production', '3 A/R de validation Studio :', ARRAY['Facturés dès le 1er retour', 'Équivalents à 50 actions pixel', 'Réservés au SMS', 'Inclus d’office dans la grille tarifaire'], 3, 'Note de la grille : 3 allers-retours systématiques. Au-delà, on sort du cadre — à dire au client dès le devis.'),
  (361, 'Chefferie de projet et production', 'Approche budgétaire vidéo (conception, tournage, montage) :', ARRAY['Sur demande au studio, via le parcours Monday de l’outil tarifs', 'PU unique 0,15 € comme une enchère', 'Incluse dans PMax'], 0, 'Ces lignes n''ont pas de tarif unitaire. Le devis Studio envoie vers l''approche budgétaire, ce n''est pas au commercial d''inventer un prix.'),
  (362, 'Chefferie de projet et production', 'Rétroplanning + devis Studio + calculateur : le bon réflexe production ?', ARRAY['Tout garder en local sans compte', 'Sauvegarder dans Mes projets et partager un planning daté', 'Remplacer Monday par un dark post', 'Sauter la création'], 1, 'Le guide d''utilisation articule Stratégie / Mon espace / Documents. Le CP s''appuie sur ces traces, pas sur des versions e-mail perdues.'),
  (363, 'Chefferie de projet et production', 'Un brief créa META incomplet (1 seul format) bloque surtout…', ARRAY['Le RCS', 'Le Search exact', 'La production Studio (il en faut 3 : carré, vertical, horizontal)'], 2, 'La chefferie recadre le besoin avant tournage / graphisme. Le guide des formats V8.2 est la bible à annexer au brief.'),
  (364, 'Chefferie de projet et production', 'Rôle du CP vis-à-vis des bilans ?', ARRAY['S’assurer que le client a le bilan interactif et comprend les KPI', 'Créer le pixel à la place du TM', 'Cibler les mineurs'], 0, 'Rapports à J+ (max 48 h) puis bilan de fin : c''est dans le périmètre chefferie (rapports, besoins clients) autant que TM.'),
  (365, 'Chefferie de projet et production', 'Monday.com dans l''écosystème Link Academy sert notamment à…', ARRAY['Potentiels / audience et approches budgétaires vidéo', 'Héberger les quizzes', 'Remplacer Google Ads', 'Stocker les UTM'], 0, 'Cartographie (potentiels), Studio (approche budgétaire), guide chefferie (process Monday). C''est l''outil de flux, pas une régie pub.')
